#[derive(Debug, Clone, Serialize, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
pub struct PlatformCapabilities {
    pub platform: &'static str,
    pub native_ocr: bool,
    pub native_ocr_formats: Vec<&'static str>,
}

/// Native feature flags come from the compiled Rust target, never WebView user-agent hints.
pub fn platform_capabilities() -> PlatformCapabilities {
    let platform = if cfg!(target_os = "macos") {
        "macos"
    } else if cfg!(target_os = "windows") {
        "windows"
    } else if cfg!(target_os = "linux") {
        "linux"
    } else {
        "other"
    };
    PlatformCapabilities {
        platform,
        native_ocr: cfg!(any(target_os = "macos", target_os = "windows")),
        native_ocr_formats: if cfg!(any(target_os = "macos", target_os = "windows")) {
            vec!["image/png", "image/jpeg"]
        } else {
            Vec::new()
        },
    }
}

