// ============================================================================
// 辅助函数
// ============================================================================

/// 解析任务模式字符串。
fn parse_mode(mode: &str) -> Result<TaskMode, String> {
    match mode {
        "ask" => Ok(TaskMode::Ask),
        "edit" => Ok(TaskMode::Edit),
        "auto" => Ok(TaskMode::Auto),
        "plan" => Ok(TaskMode::Plan),
        _ => Err(format!(
            "invalid mode: {mode} (expected ask/edit/auto/plan)"
        )),
    }
}

/// 解析权限决定字符串。
fn parse_decision(decision: &str) -> Result<PermissionDecision, String> {
    match decision {
        "allow" => Ok(PermissionDecision::Allow),
        "allow_always" => Ok(PermissionDecision::AllowAlways),
        "deny" => Ok(PermissionDecision::Deny),
        _ => Err(format!(
            "invalid decision: {decision} (expected allow/allow_always/deny)"
        )),
    }
}

/// 将错误转换为 String。泛型实现，兼容 ProductError / agent_error::Error / std::io::Error 等。
fn err_str<E: std::fmt::Display>(e: E) -> String {
    e.to_string()
}

/// Preserve structured user errors across legacy `Result<T, String>` command paths while older
/// internal errors keep their existing textual behavior. The frontend recognizes this JSON shape
/// and localizes `code + args`; `debug_detail` remains outside the visible message.
fn product_err_str(error: ProductError) -> String {
    match error {
        ProductError::UserFacing(error) => serde_json::to_string(&error).unwrap_or(error.code),
        error => error.to_string(),
    }
}

/// 从已打开的 workspace 记录得到一个规范且存在的根目录。
///
/// 前端不能把任意路径当作工作区作用域传入：路径必须已经由 `workspace_open`
/// 校验并持久化。每次使用前重新 canonicalize，避免挂载点/符号链接变化后继续
/// 按旧字符串访问。
fn workspace_root(state: &CommandState, workspace_path: &str) -> Result<PathBuf, String> {
    let workspace = WorkspaceService::new(&state.db)
        .get(workspace_path)
        .map_err(err_str)?
        .ok_or_else(|| "workspace is not open; choose the folder before using it".to_string())?;
    let root = PathBuf::from(&workspace.canonical_path)
        .canonicalize()
        .map_err(|e| format!("workspace is no longer accessible: {e}"))?;
    if !root.is_dir() {
        return Err("workspace path is not a directory".to_string());
    }
    Ok(root)
}

/// 判断持久化的 workspace 键是否仍指向同一个物理根目录。
///
/// Windows 的 `canonicalize` 会为本地路径添加 `\\?\` 前缀，旧记录或测试夹具可能
/// 保留普通盘符写法。这里按物理路径做 fail-closed 的幂等判断；解析失败或指向其他
/// 目录时仍由调用方拒绝改绑。
fn workspace_binding_matches_root(binding: &str, root: &Path) -> bool {
    let binding = Path::new(binding);
    binding == root
        || binding
            .canonicalize()
            .is_ok_and(|canonical| canonical == root)
}

/// 已附加工作区可供用户直接操作；所有文件路径仍在 `workspace_root` 的 PathGuard
/// 边界内。Agent 自主调用是否需要批准由项目 `access_mode` 决定。
fn attached_workspace_root(state: &CommandState, workspace_path: &str) -> Result<PathBuf, String> {
    workspace_root(state, workspace_path)
}

fn attached_task_workspace_root(state: &CommandState, task_id: &str) -> Result<PathBuf, String> {
    let task = TaskRepository::new(&state.db)
        .get(task_id)
        .map_err(err_str)?
        .ok_or_else(|| format!("task not found: {task_id}"))?;
    resolve_task_workspace_binding(&state.db, &task)
        .map(|binding| binding.root().to_path_buf())
        .map_err(product_err_str)
}

#[cfg(test)]
fn task_workspace_binding_from_db(
    db: &Database,
    task: &Task,
) -> Result<(Option<String>, ProjectAccessMode), String> {
    resolve_task_workspace_binding(db, task)
        .map(|binding| binding.into_runtime_parts())
        .map_err(product_err_str)
}

fn resolve_workspace_path(root: &Path, path: &str) -> Result<PathBuf, String> {
    let guard = PathGuard::new(root.to_path_buf()).map_err(err_str)?;
    let requested = PathBuf::from(path);
    let candidate = if requested.is_absolute() {
        requested
    } else {
        guard.root().join(requested)
    };
    // 回滚/审核目标是已存在文件。优先 canonicalize 以消解持久化拼写与当前 root 的
    // 差异（macOS 的 /var -> /private/var、Windows 的 8.3 短名 RUNNER~1 -> runneradmin
    // 与 \\?\ 前缀），并在 canonical 结果上校验 containment；canonicalize 失败（路径
    // 尚不存在）才回退到词法 strip 的类型化解析，覆盖即将创建文件的调用方。
    if let Ok(canonical) = candidate.canonicalize() {
        if canonical.starts_with(guard.root()) {
            return Ok(canonical);
        }
        return Err(format!(
            "absolute path {} is outside workspace root {}",
            candidate.display(),
            guard.root().display()
        ));
    }
    guard
        .resolve_path(&candidate)
        .map(|resolved| resolved.canonical().to_path_buf())
        .map_err(err_str)
}

/// 将用户/历史路径解析成安全的物理路径，同时找回与其等价的持久化路径键。
/// Windows 上 `canonicalize` 可能添加 `\\?\\` 前缀；如果直接拿规范化路径查
/// 旧 baseline，会误判为没有基线。这里始终以 PathGuard 验证物理路径，再按
/// canonical 等价关系复用已记录的键。
async fn rollback_target(
    service: &ChangeService<'_>,
    task_id: &str,
    root: &Path,
    requested_path: &str,
) -> Result<(String, PathBuf), String> {
    let physical_path = resolve_workspace_path(root, requested_path)?;
    for baseline in service.list_baselines(task_id).await.map_err(err_str)? {
        let stored = PathBuf::from(&baseline.path);
        let candidate = if stored.is_absolute() {
            stored
        } else {
            root.join(stored)
        };
        // 基线按调用方当时的拼写持久化（Windows 的 8.3 短名或 junction 父目录会原样
        // 保留），词法 strip 会因拼写差异漏匹配同一物理文件。canonicalize 后与已经过
        // PathGuard 校验的 physical_path 做恒等比较，等价于旧的 canonicalize-first 语义；
        // 只有完全相等才复用基线键，containment 由 physical_path 传递保证。
        if candidate
            .canonicalize()
            .is_ok_and(|canonical| canonical == physical_path)
        {
            return Ok((baseline.path, physical_path));
        }
    }
    Ok((physical_path.display().to_string(), physical_path))
}

