// 任务命令
// ============================================================================

/// 手动上下文压缩结果。可见聊天记录不删除；`before_messages` / `after_messages`
/// 描述的是下一轮模型使用的工作集。
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct ContextCompactionResult {
    pub compacted: bool,
    pub before_messages: usize,
    pub after_messages: usize,
}

pub async fn task_create(
    state: &CommandState,
    workspace_path: Option<&str>,
    title: &str,
    goal: &str,
    mode: &str,
) -> Result<Task, String> {
    task_create_with_agent(state, workspace_path, title, goal, mode, None, None).await
}

/// 创建任务并可选地绑定一个已就绪的模型服务。
///
/// 保留无 provider 的旧入口用于兼容既有 IPC/测试；桌面端新建会话会传入显式选择，
/// 从而不因全局默认服务随后变化而改变该会话的后续运行。
pub async fn task_create_with_provider(
    state: &CommandState,
    workspace_path: Option<&str>,
    title: &str,
    goal: &str,
    mode: &str,
    provider_name: Option<&str>,
) -> Result<Task, String> {
    task_create_with_agent(
        state,
        workspace_path,
        title,
        goal,
        mode,
        provider_name,
        None,
    )
    .await
}

/// 创建任务并绑定主 Agent 引擎。未显式传入时采用设置中的默认值；任务一旦创建，
/// 该选择会持久化，后续全局默认变化不会悄悄改变既有会话。
pub async fn task_create_with_agent(
    state: &CommandState,
    workspace_path: Option<&str>,
    title: &str,
    goal: &str,
    mode: &str,
    provider_name: Option<&str>,
    agent_engine: Option<&str>,
) -> Result<Task, String> {
    task_create_with_agent_typed(
        state,
        workspace_path,
        title,
        goal,
        mode,
        provider_name,
        agent_engine,
    )
    .await
    .map_err(err_str)
}

/// Typed creation path used by transports that can preserve structured product errors.
pub async fn task_create_with_agent_typed(
    state: &CommandState,
    workspace_path: Option<&str>,
    title: &str,
    goal: &str,
    mode: &str,
    provider_name: Option<&str>,
    agent_engine: Option<&str>,
) -> Result<Task, ProductError> {
    let task = build_new_task(
        state,
        workspace_path,
        title,
        goal,
        mode,
        provider_name,
        agent_engine,
    )
    .map_err(ProductError::Other)?;
    TaskRepository::new(&state.db).create(&task)?;
    let branch = SessionBranchRepository::new(&state.db).ensure_active(&task.id)?;
    TaskEventStore::new(&state.db).append_for_branch(
        &task.id,
        &branch.id,
        TaskEventType::TaskCreated,
    )?;
    Ok(task)
}

fn build_new_task(
    state: &CommandState,
    workspace_path: Option<&str>,
    title: &str,
    goal: &str,
    mode: &str,
    provider_name: Option<&str>,
    agent_engine: Option<&str>,
) -> Result<Task, String> {
    let mode = parse_mode(mode)?;
    let workspace_path = workspace_path
        .filter(|path| !path.trim().is_empty())
        .map(|path| workspace_root(state, path).map(|root| root.display().to_string()))
        .transpose()?;
    let config = SettingsService::new(state.config_dir.clone())
        .load_global_unvalidated()
        .map_err(err_str)?;
    let agent_engine = match agent_engine
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        Some(value) => AgentEngine::try_from_str(value)
            .ok_or_else(|| "主 Agent 只支持 r_code 或 codex".to_string())?,
        None => match config.orchestration.default_agent_engine {
            agent_config::MainAgentEngine::Native => AgentEngine::RCode,
            agent_config::MainAgentEngine::Codex => AgentEngine::Codex,
        },
    };
    if mode == TaskMode::Plan && agent_engine != AgentEngine::RCode {
        return Err("Codex CLI 主 Agent 暂不支持 Plan 模式；请选择 R-Code 内置 Agent".to_string());
    }
    let provider_name = if agent_engine == AgentEngine::RCode {
        validate_selected_provider(state, provider_name)?
    } else {
        // Codex 使用本机 CLI 的模型与登录配置；R-Code provider 仍保留为切回时的候选，
        // 但新建 Codex 会话不因自定义 provider 尚未配置而失败。
        provider_name
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(str::to_string)
    };
    let mut task = Task::new(workspace_path, title, goal, mode);
    task.provider_name = provider_name;
    task.agent_engine = agent_engine;
    Ok(task)
}

/// Create and persist one empty project conversation before its first message. Naming, the
/// five-conversation limit, initial branch creation, and the TaskCreated audit event share one
/// SQLite write transaction so concurrent UI clicks cannot create duplicates or exceed the cap.
pub async fn project_conversation_create(
    state: &CommandState,
    workspace_path: &str,
) -> Result<Task, String> {
    project_conversation_create_typed(state, workspace_path)
        .await
        .map_err(err_str)
}

/// Typed project-plus creation path used by Tauri to preserve the stable limit code.
pub async fn project_conversation_create_typed(
    state: &CommandState,
    workspace_path: &str,
) -> Result<Task, ProductError> {
    if workspace_path.trim().is_empty() {
        return Err(ProductError::Other(
            "新建项目对话前需要先选择项目".to_string(),
        ));
    }
    let mut task = build_new_task(
        state,
        Some(workspace_path),
        "新对话",
        "",
        "edit",
        None,
        None,
    )
    .map_err(ProductError::Other)?;
    TaskRepository::new(&state.db).create_project_conversation(&mut task)?;
    Ok(task)
}

fn task_matches_codex_prepare_identity(
    state: &CommandState,
    task_id: &str,
    workspace: &Path,
    expected_branch_id: &str,
) -> Result<bool, String> {
    let Some(task) = TaskRepository::new(&state.db)
        .get(task_id)
        .map_err(err_str)?
    else {
        return Ok(false);
    };
    if task.state == TaskState::Archived || task.agent_engine != AgentEngine::Codex {
        return Ok(false);
    }
    let current_workspace =
        resolve_task_workspace_binding(&state.db, &task).map_err(product_err_str)?;
    let workspace_matches = current_workspace.root() == workspace;
    let branch_matches = SessionBranchRepository::new(&state.db)
        .active(task_id)
        .map_err(err_str)?
        .is_some_and(|branch| branch.id == expected_branch_id);
    Ok(workspace_matches && branch_matches)
}

#[allow(clippy::too_many_arguments)]
async fn prepare_codex_task_transport(
    state: &CommandState,
    task_id: &str,
    expected_branch_id: &str,
    workspace: &Path,
    cli_path: PathBuf,
    config_path: &Path,
    startup_timeout: Duration,
) -> Result<(), String> {
    let prepared = state
        .codex_app_server
        .prepare_tracked(
            task_id,
            workspace,
            Some(cli_path),
            config_path,
            startup_timeout,
        )
        .await;
    // A fire-and-forget prepare releases the task bridge before process startup. `/clear`, archive,
    // workspace changes, and engine changes can therefore win while initialize is in flight. The
    // active branch is part of the identity: a transport prepared for the pre-clear branch must
    // never be published back into the registry after clear invalidated it.
    let identity_is_current =
        task_matches_codex_prepare_identity(state, task_id, workspace, expected_branch_id)?;
    if !identity_is_current {
        if let Ok(preparation) = &prepared {
            state
                .codex_app_server
                .invalidate_prepared(task_id, preparation)
                .await;
        }
        return Ok(());
    }
    if let Err(error) = prepared {
        tracing::warn!(task_id, %error, "failed to prepare Codex App Server transport");
        return Err("Codex 会话暂未完成预热，将在首次发送时重试。".to_string());
    }
    Ok(())
}

/// Prepare an empty task without starting a run or writing a user message.
///
/// Native R-Code tasks retain the constructed provider runtime and an empty runtime session in
/// their task-local bridge. Codex tasks retain only an initialized task-scoped App Server
/// transport; `thread/start` and `turn/start` still wait for the first real user message.
pub async fn task_prepare(state: &CommandState, task_id: &str) -> Result<(), String> {
    let task_agent = state.agent.bridge_for(task_id).await;
    let mut bridge = task_agent.lock().await;
    let task = TaskRepository::new(&state.db)
        .get(task_id)
        .map_err(err_str)?
        .ok_or_else(|| format!("task not found: {task_id}"))?;
    if task.state == TaskState::Archived {
        return Err("会话已归档，不能准备运行环境".to_string());
    }
    let branch = SessionBranchRepository::new(&state.db)
        .ensure_active(task_id)
        .map_err(err_str)?;
    if task_has_active_main_run(&state.db, task_id, &bridge)? {
        // The first send can legitimately win the race with a fire-and-forget prepare request.
        // That run has already completed every preparation this command is allowed to perform.
        return Ok(());
    }
    ensure_session_log(
        &state.session_store,
        &state.sessions_dir,
        &branch.storage_id,
    )
    .await?;

    if task.agent_engine == AgentEngine::Codex {
        let workspace = resolve_task_workspace_binding(&state.db, &task)
            .map_err(product_err_str)?
            .root()
            .to_path_buf();
        drop(bridge);
        let cli = probe_authenticated_codex_cached().await.map_err(err_str)?;
        let cli_path = cli
            .path
            .ok_or_else(|| "无法定位 Codex CLI，不能预热会话。".to_string())?;
        let config_path = codex_home_dir().join("config.toml");
        return prepare_codex_task_transport(
            state,
            task_id,
            &branch.id,
            &workspace,
            cli_path,
            &config_path,
            CODEX_APP_SERVER_START_TIMEOUT,
        )
        .await;
    }

    if bridge.real_mode.load(Ordering::Acquire) {
        ensure_real_runtime(
            &state.config_dir,
            &state.db,
            &state.tool_gateway,
            &state.mcp_manager,
            &state.subagent_config_mutations,
            &mut bridge,
            task.provider_name.as_deref(),
            task.workspace_path.as_deref(),
            &state.sessions_dir,
        )
        .await?;
    }
    ensure_runtime_session(
        &mut bridge,
        &state.db,
        &state.session_store,
        &state.sessions_dir,
        &state.config_dir,
        &task,
        &branch,
    )
    .await?;
    Ok(())
}

/// 修改会话显示名称。标题不参与模型上下文，因此无需重建 runtime。
pub async fn task_rename(state: &CommandState, task_id: &str, title: &str) -> Result<Task, String> {
    let title = title.trim();
    if title.is_empty() {
        return Err("请输入新的会话名称".to_string());
    }
    if title.chars().count() > 96 {
        return Err("会话名称不能超过 96 个字符".to_string());
    }
    let repo = TaskRepository::new(&state.db);
    let task = repo
        .get(task_id)
        .map_err(err_str)?
        .ok_or_else(|| format!("task not found: {task_id}"))?;
    if task.state == TaskState::Archived {
        return Err("会话已归档，不能再重命名".to_string());
    }
    repo.update(task_id, Some(title), None, None)
        .map_err(err_str)?;
    repo.get(task_id)
        .map_err(err_str)?
        .ok_or_else(|| format!("task not found after rename: {task_id}"))
}

fn render_host_task_context_from_store(
    plan_store: &PlanStore,
    task: &Task,
) -> Result<String, String> {
    let plan = plan_store.current_for_task(&task.id).map_err(err_str)?;
    let execution = PlanExecutionContext::from_view(plan.as_ref());
    let progress = plan.as_ref().map(|view| {
        serde_json::json!({
            "completed": view.items.iter().filter(|item| item.state == PlanItemState::Completed).count(),
            "in_progress": view.items.iter().filter(|item| item.state == PlanItemState::InProgress).count(),
            "pending": view.items.iter().filter(|item| matches!(item.state, PlanItemState::Proposed | PlanItemState::Pending)).count(),
            "blocked": view.items.iter().filter(|item| item.state == PlanItemState::Blocked).count(),
            "failed": view.items.iter().filter(|item| item.state == PlanItemState::Failed).count(),
            "total": view.items.len(),
        })
    });
    let execution_policy = match execution.status {
        PlanExecutionStatus::NoExecutingPlan => None,
        PlanExecutionStatus::ActiveFeature => Some(
            "Implement only active_feature and keep its persisted progress current. Attribute every workspace write to that feature. Do not work ahead or skip dependencies. Work directly by default: permission to use subagents is not an instruction to create them. Only genuinely independent read-only investigation or verification for this active feature may use up to two subagents in parallel; collect every result and synthesize once before deciding acceptance. Keep overlapping or mutating work with the main Agent so enhanced ownership remains deterministic. Prefer direct edit/apply_patch/create_file/delete_file tools for Plan feature writes. Writes made through shell, MCP, or external agents cannot be reliably attributed and appear only in ordinary Git review. Call plan_item_update when the feature is completed or blocked before continuing. A normal final answer does not end the run while active_feature still exists.",
        ),
        PlanExecutionStatus::Paused => Some(
            "Plan execution is paused. Do not write to the workspace through direct tools, shell, MCP, or external agents. First resume blocked_feature by calling plan_item_update with state=in_progress for the same feature and current Plan revision; only then continue implementation.",
        ),
    };
    serde_json::to_string_pretty(&serde_json::json!({
        "task": {
            "id": task.id,
            "goal": task.goal,
            "mode": task.mode,
        },
        "plan": plan.as_ref().map(|view| &view.plan),
        "items": plan.as_ref().map(|view| &view.items),
        "progress": progress,
        "pending_question_set": plan
            .as_ref()
            .and_then(|view| view.pending_question_set.as_ref()),
        "execution_status": execution.status,
        "active_feature": execution.active_feature,
        "blocked_feature": execution.blocked_feature,
        "execution_policy": execution_policy,
    }))
    .map_err(|error| format!("无法渲染 Plan 运行上下文：{error}"))
}

fn render_host_task_context(state: &CommandState, task: &Task) -> Result<String, String> {
    render_host_task_context_from_store(&state.plan_store, task)
}

pub(crate) async fn refresh_runtime_task_context_if_present(
    state: &CommandState,
    task: &Task,
) -> Result<(), String> {
    let Some(task_agent) = state.agent.existing_bridge_for(&task.id).await else {
        return Ok(());
    };
    let context = render_host_task_context(state, task)?;
    let mut bridge = task_agent.lock().await;
    let Some(runtime_session_id) = bridge
        .sessions
        .get(&task.id)
        .map(|session| session.runtime_session_id.clone())
    else {
        return Ok(());
    };
    bridge
        .kind
        .update_task_context(&runtime_session_id, task.mode, Some(context))
        .await
        .map_err(err_str)
}

fn require_task(state: &CommandState, task_id: &str) -> Result<Task, String> {
    TaskRepository::new(&state.db)
        .get(task_id)
        .map_err(err_str)?
        .ok_or_else(|| format!("task not found: {task_id}"))
}

fn require_native_plan_task(state: &CommandState, task_id: &str) -> Result<Task, String> {
    let task = require_task(state, task_id)?;
    if task.state == TaskState::Archived {
        return Err("会话已归档，不能继续 Plan 工作流".to_string());
    }
    if task.agent_engine != AgentEngine::RCode {
        return Err("Plan 模式仅支持 R-Code 内置 Agent；请先将主 Agent 切换为 R-Code".to_string());
    }
    if task.mode != TaskMode::Plan {
        return Err("当前会话未启用 Plan 模式".to_string());
    }
    Ok(task)
}

/// Update or clear the durable goal and immediately refresh any cached native session.
pub async fn task_update_goal(
    state: &CommandState,
    task_id: &str,
    goal: &str,
) -> Result<Task, String> {
    if goal.chars().count() > 20_000 {
        return Err("目标不能超过 20,000 个字符".to_string());
    }
    let task = require_task(state, task_id)?;
    if task.state == TaskState::Archived {
        return Err("会话已归档，不能修改目标".to_string());
    }
    let repo = TaskRepository::new(&state.db);
    repo.set_goal(task_id, goal).map_err(err_str)?;
    let task = require_task(state, task_id)?;
    refresh_runtime_task_context_if_present(state, &task).await?;
    Ok(task)
}

/// Switch task policy without replacing the protocol history of a cached native session.
pub async fn task_set_mode(
    state: &CommandState,
    task_id: &str,
    mode: TaskMode,
) -> Result<Task, String> {
    let task_agent = state.agent.bridge_for(task_id).await;
    let bridge = task_agent.lock().await;
    let task = require_task(state, task_id)?;
    if task.state == TaskState::Archived {
        return Err("会话已归档，不能切换模式".to_string());
    }
    if mode == TaskMode::Plan && task.agent_engine != AgentEngine::RCode {
        return Err(
            "Codex CLI 主 Agent 暂不支持 Plan 模式；请先切换到 R-Code 内置 Agent".to_string(),
        );
    }
    if mode != task.mode && task_has_active_main_run(&state.db, task_id, &bridge)? {
        return Err("当前运行尚未结束，请先停止或等待完成后再切换模式".to_string());
    }
    TaskRepository::new(&state.db)
        .set_mode(task_id, mode)
        .map_err(err_str)?;
    drop(bridge);
    let task = require_task(state, task_id)?;
    refresh_runtime_task_context_if_present(state, &task).await?;
    Ok(task)
}

pub async fn plan_get(state: &CommandState, task_id: &str) -> Result<Option<PlanView>, String> {
    require_task(state, task_id)?;
    state.plan_store.current_for_task(task_id).map_err(err_str)
}

pub async fn plan_create(state: &CommandState, task_id: &str) -> Result<PlanView, String> {
    let task = require_native_plan_task(state, task_id)?;
    if let Some(current) = state
        .plan_store
        .current_for_task(task_id)
        .map_err(err_str)?
        .filter(|view| !matches!(view.plan.state, PlanState::Completed | PlanState::Cancelled))
    {
        return Ok(current);
    }
    // §14.2：UI plan_create 也必须接收宿主解析的冻结 profile；存储层不读设置。
    let profile = state.planning.resolve_profile_for_task_id(task_id);
    let view = state
        .plan_store
        .create_plan_with_profile(
            &CreatePlanInput {
                task_id: task_id.to_string(),
            },
            &profile,
        )
        .map_err(err_str)?;
    refresh_runtime_task_context_if_present(state, &task).await?;
    Ok(view)
}

fn render_plan_continuation(question_set: &PlanQuestionSet) -> Result<String, String> {
    let scope_decision = question_set.kind == PlanQuestionSetKind::ScopeDecision;
    match question_set.state {
        PlanQuestionSetState::Answered => {}
        PlanQuestionSetState::Skipped => {
            return Ok(if scope_decision {
                "用户跳过了本轮范围决策，请恢复原任务并继续。".to_string()
            } else {
                "已跳过本轮计划问题，请结合现有上下文继续完善同一计划。".to_string()
            });
        }
        PlanQuestionSetState::Pending => return Err("问题集尚未回答，不能恢复 Plan".to_string()),
    }

    let mut rendered = if scope_decision {
        "范围决策已回答，请恢复原任务并继续：".to_string()
    } else {
        "计划问题已回答，请根据以下选择继续完善同一计划：".to_string()
    };
    for question in &question_set.questions {
        let answer = match question.answer.as_ref() {
            Some(PlanQuestionAnswer::Option { option_id }) => question
                .options
                .iter()
                .find(|option| option.id == *option_id)
                .map(|option| option.label.as_str())
                .unwrap_or("已选择一个选项"),
            Some(PlanQuestionAnswer::FreeForm { text }) => text.as_str(),
            None => "未回答",
        };
        rendered.push_str(&format!("\n- {}：{}", question.question, answer));
    }
    rendered.push_str("\n\n请不要重复询问这些已解决的问题。");
    Ok(rendered)
}

/// CAS-claim and resume a resolved question set. Concurrent calls cannot dispatch twice. A
/// process crash after the claim is recovered as a visible failed continuation on next startup.
async fn dispatch_plan_continuation(
    state: &CommandState,
    task_id: &str,
    question_set_id: &str,
) -> Result<(), String> {
    let Some(claimed) = state
        .plan_store
        .claim_continuation(task_id, question_set_id)
        .map_err(err_str)?
    else {
        return Ok(());
    };
    let message = match render_plan_continuation(&claimed) {
        Ok(message) => message,
        Err(error) => {
            let _ = state.plan_store.mark_continuation_failed(
                task_id,
                question_set_id,
                &format!("PLAN_CONTINUATION_RENDER_FAILED: {error}"),
            );
            return Err(format!("回答已保存，但无法生成 Plan 恢复消息：{error}"));
        }
    };
    if claimed.kind == PlanQuestionSetKind::ScopeDecision {
        if let Some(restore_mode) = claimed.restore_mode {
            TaskRepository::new(&state.db)
                .set_mode(task_id, restore_mode)
                .map_err(err_str)?;
            let task = require_task(state, task_id)?;
            refresh_runtime_task_context_if_present(state, &task).await?;
        }
    }
    if let Err(error) = agent_send_with_mode(state, task_id, &message, AgentSendMode::Auto).await {
        if let Err(mark_error) = state.plan_store.mark_continuation_failed(
            task_id,
            question_set_id,
            &format!("PLAN_CONTINUATION_DISPATCH_FAILED: {error}"),
        ) {
            tracing::error!(
                task_id,
                question_set_id,
                "could not mark failed Plan continuation: {mark_error}"
            );
        }
        return Err(format!(
            "回答已保存，但恢复 Plan 运行失败，可点击重试：{error}"
        ));
    }
    if let Err(error) = state
        .plan_store
        .mark_continuation_dispatched(task_id, question_set_id)
    {
        let _ = state.plan_store.mark_continuation_failed(
            task_id,
            question_set_id,
            &format!("PLAN_CONTINUATION_ACK_FAILED: {error}"),
        );
        return Err(format!(
            "Plan 恢复消息已提交，但确认状态保存失败；为避免永久卡住，已标记为可重试：{error}"
        ));
    }
    Ok(())
}

pub async fn plan_answer(
    state: &CommandState,
    task_id: &str,
    input: AnswerPlanQuestionsInput,
) -> Result<PlanView, String> {
    let question_set_id = input.question_set_id.clone();
    let set = state
        .plan_store
        .get_question_set(task_id, &question_set_id)
        .map_err(err_str)?;
    if set.kind == PlanQuestionSetKind::ScopeDecision {
        // 范围决策第一次回答后会恢复为原 Agent 模式；重复提交同一答案时必须仍可
        // 幂等返回，不能再用 Plan 模式守卫误拒。
        let task = require_task(state, task_id)?;
        if task.state == TaskState::Archived {
            return Err("会话已归档，不能继续范围决策".to_string());
        }
        if task.agent_engine != AgentEngine::RCode {
            return Err("范围决策仅支持 R-Code 内置 Agent".to_string());
        }
    } else {
        require_native_plan_task(state, task_id)?;
    }
    state
        .plan_store
        .answer_questions(task_id, &input)
        .map_err(err_str)?;
    let task = require_task(state, task_id)?;
    refresh_runtime_task_context_if_present(state, &task).await?;
    dispatch_plan_continuation(state, task_id, &question_set_id).await?;
    state
        .plan_store
        .current_for_task(task_id)
        .map_err(err_str)?
        .ok_or_else(|| "Plan 在回答后不可用".to_string())
}

pub async fn plan_retry_continuation(
    state: &CommandState,
    task_id: &str,
    question_set_id: &str,
) -> Result<PlanView, String> {
    let set = state
        .plan_store
        .get_question_set(task_id, question_set_id)
        .map_err(err_str)?;
    if set.kind == PlanQuestionSetKind::ScopeDecision {
        // 范围决策派发失败时任务可能已恢复为原 Agent 模式；重试不能再用
        // `require_native_plan_task` 误拒。只要任务未归档且仍属于 R-Code 即可。
        require_task(state, task_id)?;
    } else {
        require_native_plan_task(state, task_id)?;
    }
    state
        .plan_store
        .retry_continuation(task_id, question_set_id)
        .map_err(err_str)?;
    dispatch_plan_continuation(state, task_id, question_set_id).await?;
    state
        .plan_store
        .current_for_task(task_id)
        .map_err(err_str)?
        .ok_or_else(|| "Plan 在重试后不可用".to_string())
}

fn render_plan_implementation_message(view: &PlanView) -> Result<String, String> {
    let active = view
        .items
        .iter()
        .find(|item| item.state == PlanItemState::InProgress)
        .ok_or_else(|| {
            "Plan 已批准，但没有可执行的 in_progress 功能项；请检查依赖关系后继续".to_string()
        })?;
    Ok(format!(
        "计划已确认，请实施当前功能事项“{}”。\n\n验收边界：{}\n\n只处理这一项，不要跳过依赖或提前实现后续事项；优先使用直接文件编辑工具，以便变更能够归属到该功能事项。完成或受阻时请更新事项状态。",
        active.title, active.description
    ))
}

fn render_plan_implementation_continuation(view: &PlanView) -> Result<(String, String), String> {
    let active = view
        .items
        .iter()
        .find(|item| item.state == PlanItemState::InProgress)
        .ok_or_else(|| "Plan 当前没有可续接的 in_progress 功能项".to_string())?;
    Ok((
        active.id.clone(),
        format!(
            "继续实施当前 Plan 功能事项“{}”。\n\n验收边界：{}\n\n沿用现有计划、工作区变更和进度，只处理这一项；先核对上一轮已完成的工作，再补齐剩余实现与验证。完成或受阻时请更新事项状态。",
            active.title, active.description
        ),
    ))
}

/// Claim and durably stage the approved Plan while the caller holds the task-local runtime lock.
/// The SQLite transaction changes task mode, creates/reuses one deterministic queue row, and
/// acknowledges the Plan handoff together, so no crash window can leave a hidden implementation.
fn stage_plan_implementation(
    state: &CommandState,
    task_id: &str,
    plan_id: &str,
    current: PlanView,
) -> Result<PlanView, String> {
    let branch = SessionBranchRepository::new(&state.db)
        .ensure_active(task_id)
        .map_err(err_str)?;
    let message = render_plan_implementation_message(&current)?;
    let Some(_claimed) = state
        .plan_store
        .claim_implementation_dispatch(task_id, plan_id)
        .map_err(err_str)?
    else {
        return Ok(current);
    };
    match state
        .plan_store
        .stage_implementation_dispatch(task_id, plan_id, &branch.id, &message)
    {
        Ok(view) => {
            // docs §8.6：implementation dispatch 事务成功（task.mode=auto +
            // dispatch=dispatched + 队列入队）后发出 RestoredFull 审计事件。
            // 下一 run 的 prepare_runtime_session 派生 ExecutionFull，恢复完整
            // 目录与 Standard 注入；worker 侧断言非 Plan 策略绝不再看到收窄目录。
            state.emit_agent_event(
                task_id,
                &AgentEvent::CatalogAnchor {
                    phase: CatalogAnchorPhase::RestoredFull,
                    catalog: "plan_native".to_string(),
                    tool_count: 0,
                    full_tool_count: 0,
                },
            );
            Ok(view)
        }
        Err(error) => {
            let error = format!("PLAN_IMPLEMENTATION_STAGE_FAILED: {error}");
            if let Err(mark_error) = state
                .plan_store
                .mark_implementation_dispatch_failed(task_id, plan_id, &error)
            {
                tracing::error!(
                    task_id,
                    plan_id,
                    "could not persist failed Plan handoff: {mark_error}"
                );
            }
            Err(format!(
                "Plan 已批准，但实施请求暂未入队；可点击重试：{}",
                error.trim_start_matches("PLAN_IMPLEMENTATION_STAGE_FAILED: ")
            ))
        }
    }
}

async fn drain_plan_implementation_queue(
    state: &CommandState,
    task_id: &str,
    plan_id: &str,
) -> Result<PlanView, String> {
    let task = require_task(state, task_id)?;
    refresh_runtime_task_context_if_present(state, &task).await?;
    dispatch_next_queued(queued_dispatch_resources(state), task_id.to_string()).await;
    state
        .plan_store
        .get_plan(task_id, plan_id)
        .map_err(err_str)?
        .ok_or_else(|| "Plan 不存在或不属于当前会话".to_string())
}

pub async fn plan_approve(
    state: &CommandState,
    task_id: &str,
    plan_id: &str,
    expected_revision: u64,
) -> Result<PlanView, String> {
    let task_agent = state.agent.bridge_for(task_id).await;
    let bridge = task_agent.lock().await;
    let task = require_task(state, task_id)?;
    if task.state == TaskState::Archived {
        return Err("会话已归档，不能批准 Plan".to_string());
    }
    if task.agent_engine != AgentEngine::RCode {
        return Err("Plan 模式仅支持 R-Code 内置 Agent；请先将主 Agent 切换为 R-Code".to_string());
    }
    if !matches!(task.mode, TaskMode::Plan | TaskMode::Auto | TaskMode::Edit) {
        return Err("当前会话未启用 Plan 工作流".to_string());
    }
    if task_has_active_main_run(&state.db, task_id, &bridge)? {
        return Err("当前运行尚未结束，请先停止或等待完成后再批准 Plan".to_string());
    }
    let (view, _newly_approved) = state
        .plan_store
        .approve_plan_with_outcome(
            task_id,
            &ApprovePlanInput {
                plan_id: plan_id.to_string(),
                expected_revision,
            },
        )
        .map_err(err_str)?;
    let view = stage_plan_implementation(state, task_id, plan_id, view)?;
    drop(bridge);
    let _ = view;
    drain_plan_implementation_queue(state, task_id, plan_id).await
}

pub async fn plan_retry_implementation(
    state: &CommandState,
    task_id: &str,
    plan_id: &str,
) -> Result<PlanView, String> {
    let task_agent = state.agent.bridge_for(task_id).await;
    let bridge = task_agent.lock().await;
    let task = require_task(state, task_id)?;
    if task.state == TaskState::Archived {
        return Err("会话已归档，不能重试 Plan 实施".to_string());
    }
    if task.agent_engine != AgentEngine::RCode {
        return Err("Plan 模式仅支持 R-Code 内置 Agent；请先将主 Agent 切换为 R-Code".to_string());
    }
    if task_has_active_main_run(&state.db, task_id, &bridge)? {
        return Err("当前运行尚未结束，无需重复启动 Plan 实施".to_string());
    }
    let view = state
        .plan_store
        .get_plan(task_id, plan_id)
        .map_err(err_str)?
        .ok_or_else(|| "Plan 不存在或不属于当前会话".to_string())?;
    let view =
        if view.plan.implementation_dispatch_state == PlanImplementationDispatchState::Dispatched {
            if !matches!(task.state, TaskState::Interrupted | TaskState::ReviewReady) {
                return Err("只有已中断或已有部分成果待审查的 Plan 才能续接当前功能".to_string());
            }
            let branch = SessionBranchRepository::new(&state.db)
                .ensure_active(task_id)
                .map_err(err_str)?;
            let (item_id, message) = render_plan_implementation_continuation(&view)?;
            state
                .plan_store
                .stage_implementation_continuation(task_id, plan_id, &branch.id, &item_id, &message)
                .map_err(err_str)?
        } else {
            stage_plan_implementation(state, task_id, plan_id, view)?
        };
    drop(bridge);
    let _ = view;
    drain_plan_implementation_queue(state, task_id, plan_id).await
}

pub async fn plan_cancel(
    state: &CommandState,
    task_id: &str,
    plan_id: &str,
    expected_revision: u64,
) -> Result<PlanView, String> {
    let task_agent = state.agent.bridge_for(task_id).await;
    let bridge = task_agent.lock().await;
    let task = require_task(state, task_id)?;
    if task.state == TaskState::Archived {
        return Err("会话已归档，不能取消 Plan".to_string());
    }
    if task_has_active_main_run(&state.db, task_id, &bridge)? {
        return Err("当前运行尚未结束，请先停止或等待完成后再取消 Plan".to_string());
    }
    let view = state
        .plan_store
        .cancel_plan(
            task_id,
            &CancelPlanInput {
                plan_id: plan_id.to_string(),
                expected_revision,
            },
        )
        .map_err(err_str)?;
    drop(bridge);
    let task = require_task(state, task_id)?;
    refresh_runtime_task_context_if_present(state, &task).await?;
    Ok(view)
}

