fn task_has_active_main_run(
    db: &Database,
    task_id: &str,
    bridge: &AgentBridge,
) -> Result<bool, String> {
    if bridge.active.is_some() {
        return Ok(true);
    }
    AgentRunRepository::new(db)
        .get_active_run(task_id)
        .map(|run| run.is_some())
        .map_err(err_str)
}

/// Revalidate an explicit external-child launch while holding the task-local bridge lock.
/// `agent_abort` uses the same lock and publishes `Interrupted` before cancelling runtimes, so
/// either this check/reservation wins first (and abort will see the new child) or the stop wins
/// first (and delegation is rejected). There is no post-stop reservation gap.
fn active_native_parent_for_delegation(
    db: &Database,
    task_id: &str,
    branch_id: &str,
    expected_parent_id: &str,
    bridge: &AgentBridge,
) -> Result<AgentRun, String> {
    let task = TaskRepository::new(db)
        .get(task_id)
        .map_err(err_str)?
        .ok_or_else(|| format!("task not found: {task_id}"))?;
    if !matches!(task.state, TaskState::Exploring | TaskState::InProgress) {
        return Err("当前主运行已经停止，不能再启动新的外部子代理".to_string());
    }
    if bridge.closing_run_id.as_deref() == Some(expected_parent_id) {
        return Err("当前主运行正在收尾，不能再启动新的外部子代理".to_string());
    }
    let active = bridge
        .active
        .as_ref()
        .filter(|active| {
            active.task_id == task_id
                && active.branch_id == branch_id
                && active.run_id == expected_parent_id
        })
        .ok_or_else(|| "当前主运行已经结束或已被替换".to_string())?;
    let parent = AgentRunRepository::new(db)
        .get(&active.run_id)
        .map_err(err_str)?
        .filter(|run| {
            run.ended_at.is_none()
                && run.agent_kind == AgentKind::Main
                && run.runtime_kind == AgentRunRuntimeKind::Native
        })
        .ok_or_else(|| "当前原生主运行已经结束，不能再委派外部子代理".to_string())?;
    Ok(parent)
}

/// Seal a drained native parent while holding its task-local bridge lock.
///
/// Explicit delegation takes this same lock through validation and registry reservation. Thus a
/// child either reserves before this no-child check (and keeps the drain loop alive), or observes
/// `closing_run_id` afterwards and is rejected. There is no ended-parent ghost-child window.
async fn try_mark_native_parent_closing(
    bridge: &mut AgentBridge,
    external_agents: &ExternalAgentRegistry,
    active: &ActiveRun,
) -> bool {
    if bridge.closing_run_id.as_deref() == Some(active.run_id.as_str()) {
        return true;
    }
    if bridge
        .active
        .as_ref()
        .is_none_or(|current| current.run_id != active.run_id)
        || external_agents.has_for_parent_run(&active.run_id).await
    {
        return false;
    }
    bridge.closing_run_id = Some(active.run_id.clone());
    true
}

/// 清空当前任务的消息上下文，但保留同一任务、工作区绑定、显式 Goal、文件变更与
/// 可审计历史。实现上切换到一条没有父消息副本的活跃分支，因而不覆盖或删除旧 JSONL。
pub async fn task_clear_context(
    state: &CommandState,
    task_id: &str,
) -> Result<SessionBranch, String> {
    let task_agent = state.agent.bridge_for(task_id).await;
    let mut bridge = task_agent.lock().await;
    let task = TaskRepository::new(&state.db)
        .get(task_id)
        .map_err(err_str)?
        .ok_or_else(|| format!("task not found: {task_id}"))?;
    if task.state == TaskState::Archived {
        return Err("会话已归档，不能清空上下文".to_string());
    }
    if task_has_active_main_run(&state.db, task_id, &bridge)? {
        return Err("当前运行尚未结束，请先停止或等待完成后再清空上下文".to_string());
    }

    let source_branch = SessionBranchRepository::new(&state.db)
        .ensure_active(task_id)
        .map_err(err_str)?;
    let branch = SessionBranch::reset(task_id, &source_branch.id);
    // Write the empty log before switching the database pointer. A disk failure therefore leaves
    // the current conversation untouched; a later database failure can only leave an unreferenced
    // empty file, never destroy the source branch.
    ensure_session_log(
        &state.session_store,
        &state.sessions_dir,
        &branch.storage_id,
    )
    .await?;

    SessionBranchRepository::new(&state.db)
        .reset_context(
            &branch,
            &source_branch.id,
            !task.goal_active && !task.goal.trim().is_empty(),
        )
        .map_err(err_str)?;
    bridge.sessions.remove(task_id);

    // Clear establishes a new branch identity. Reclaim a prepared Codex transport even when no
    // run has started, and cancel an initialize that raced with this reset. Keep the task-local
    // bridge locked through invalidation and stale-approval cleanup: otherwise a first send on the
    // new branch can acquire/reuse the old slot in the gap and then be cancelled by this clear.
    // The prepare path revalidates the branch after initialize so it cannot republish the old
    // transport.
    state.codex_app_server.invalidate(task_id).await;

    // A task without an active run cannot legitimately keep an actionable approval request. Clear
    // any stale request so the fresh branch does not inherit a phantom “needs you” badge.
    for permission in state.permission_engine.pending_for_task(task_id).await {
        state.permission_engine.cancel_request(&permission.id).await;
    }
    drop(bridge);
    Ok(branch)
}

/// 从当前分支末端创建一条新的活跃分支；源分支和完整 JSONL 保持只读。
pub async fn task_fork_context(
    state: &CommandState,
    task_id: &str,
) -> Result<SessionBranch, String> {
    let task_agent = state.agent.bridge_for(task_id).await;
    let mut bridge = task_agent.lock().await;
    let task = TaskRepository::new(&state.db)
        .get(task_id)
        .map_err(err_str)?
        .ok_or_else(|| format!("task not found: {task_id}"))?;
    if task.state == TaskState::Archived {
        return Err("会话已归档，不能创建分支".to_string());
    }
    if task_has_active_main_run(&state.db, task_id, &bridge)? {
        return Err("当前运行尚未结束，请先停止或等待完成后再创建分支".to_string());
    }

    let source_branch = SessionBranchRepository::new(&state.db)
        .ensure_active(task_id)
        .map_err(err_str)?;
    ensure_session_log(
        &state.session_store,
        &state.sessions_dir,
        &source_branch.storage_id,
    )
    .await?;
    let source_path = session_file_path(&state.sessions_dir, &source_branch.storage_id);
    let source = tokio::fs::read_to_string(source_path)
        .await
        .map_err(err_str)?;
    let mut events = Vec::new();
    let mut forked_from_message_id = None;
    for (line_index, line) in source.lines().enumerate() {
        if line.trim().is_empty() {
            continue;
        }
        let event = serde_json::from_str::<SessionEvent>(line)
            .map_err(|_| "会话历史存在无法恢复的记录".to_string())?;
        if matches!(event, SessionEvent::Message(_)) {
            forked_from_message_id =
                Some(format!("{}:{}", source_branch.storage_id, line_index + 1));
        }
        events.push(event);
    }
    let forked_from_message_id =
        forked_from_message_id.ok_or_else(|| "当前会话还没有可分支的消息".to_string())?;
    let branch = SessionBranch::fork(task_id, &source_branch.id, &forked_from_message_id);
    match events.first_mut() {
        Some(SessionEvent::Meta(meta)) => {
            meta.id = branch.storage_id.clone();
            meta.created_at = chrono::Utc::now();
        }
        _ => return Err("会话缺少元数据，无法创建分支".to_string()),
    }
    state
        .session_store
        .write_session_atomic(&branch.storage_id, &events)
        .await
        .map_err(err_str)?;
    SessionBranchRepository::new(&state.db)
        .create_fork(&branch)
        .map_err(err_str)?;
    TaskEventStore::new(&state.db)
        .append_for_branch(task_id, &branch.id, TaskEventType::SessionBranched)
        .map_err(err_str)?;

    bridge.sessions.remove(task_id);
    Ok(branch)
}

const COMPACTION_KEEP_FIRST: usize = 1;
const COMPACTION_KEEP_RECENT: usize = 10;
const COMPACTION_MIN_MESSAGES: usize = COMPACTION_KEEP_FIRST + COMPACTION_KEEP_RECENT + 3;
/// 单次摘要请求的完整 user prompt 字符上限。为固定说明和可选 focus 留出空间后，
/// 每个来源块使用更小的 [`COMPACTION_SOURCE_CHARS`] 上限。
const COMPACTION_REQUEST_CHARS: usize = 120_000;
const COMPACTION_SOURCE_CHARS: usize = 110_000;
/// 单个 map/reduce 摘要的最大字符数。除防止异常 Provider 返回无限正文外，这也
/// 保证 reduce 每轮至少能把两个摘要合并为一个，不会出现不收敛循环。
const COMPACTION_SUMMARY_CHARS: usize = 20_000;
const COMPACTION_SUMMARY_MAX_TOKENS: u32 = 4_096;
const COMPACTION_SUMMARY_CONCURRENCY: usize = 3;

fn trim_chars(value: &str, max_chars: usize) -> String {
    value.chars().take(max_chars).collect()
}

fn compaction_message_source(index: usize, message: &Message) -> Result<String, String> {
    let role = match message.role {
        Role::User => "USER",
        Role::Assistant => "ASSISTANT",
    };
    let content = serde_json::to_string(&message.content)
        .map_err(|error| format!("会话第 {} 条消息无法序列化：{error}", index + 1))?;
    Ok(format!(
        "MESSAGE {} {role}:\nCONTENT_BLOCKS_JSON:\n{content}\n\n",
        index + 1
    ))
}

/// 手动压缩的原子单元：单条消息，或相邻的 assistant ToolUse + user ToolResult 对。
struct CompactionUnit {
    /// 预渲染的完整来源文本（与旧 `compaction_units` 输出一致）。
    text: String,
    /// 工具对锚点：合并 ToolUse/ToolResult 时记录 tool_use_id；否则 None。
    tool_use_id: Option<String>,
}

/// 把会话变成不可拆分的摘要单元。相邻的 assistant ToolUse 与 user ToolResult
/// 必须进入同一单元，避免 map 边界让摘要模型只看到调用或只看到证据。
fn compaction_units(messages: &[Message]) -> Result<Vec<CompactionUnit>, String> {
    let mut units = Vec::new();
    let mut index = 0usize;
    while index < messages.len() {
        let mut text = compaction_message_source(index, &messages[index])?;
        let mut tool_use_id = None;
        let pairs_with_next = messages
            .get(index + 1)
            .is_some_and(|next| manual_messages_form_tool_pair(&messages[index], next));
        if pairs_with_next {
            tool_use_id = messages[index]
                .content
                .iter()
                .find_map(ContentBlock::tool_id)
                .map(str::to_string);
            text.push_str(&compaction_message_source(index + 1, &messages[index + 1])?);
            index += 1;
        }
        units.push(CompactionUnit { text, tool_use_id });
        index += 1;
    }
    Ok(units)
}

/// 拆分超长单元时给每个子块加的前缀。工具对会带 tool_use_id，保证同一对在各 part
/// 之间仍可归并；非工具对只带 PART 序号。
fn compaction_part_header(unit: &CompactionUnit, part: usize, total: usize) -> String {
    match &unit.tool_use_id {
        Some(id) => format!("COMPACTION_PART {part}/{total} TOOL {id}:\n"),
        None => format!("COMPACTION_PART {part}/{total}:\n"),
    }
}

/// 把超长单元按 UTF-8 字符边界切成多个 ≤ COMPACTION_SOURCE_CHARS 的子块。
/// 每个子块带 PART 头；不省略任何字符，只做有界切分。
fn split_compaction_unit(unit: &CompactionUnit) -> Vec<String> {
    let total_chars = unit.text.chars().count();
    // 用 6 位占位符估算头部上界，保证“头 + 正文”不超 COMPACTION_SOURCE_CHARS。
    let header_upper = compaction_part_header(unit, 999_999, 999_999)
        .chars()
        .count();
    let body_budget = COMPACTION_SOURCE_CHARS.saturating_sub(header_upper).max(1);
    let part_count = total_chars.div_ceil(body_budget);

    let chars: Vec<char> = unit.text.chars().collect();
    let mut parts = Vec::with_capacity(part_count);
    let mut offset = 0usize;
    for part_index in 1..=part_count {
        let take = body_budget.min(total_chars - offset);
        let piece: String = chars[offset..offset + take].iter().collect();
        offset += take;
        let header = compaction_part_header(unit, part_index, part_count);
        parts.push(format!("{header}{piece}"));
    }
    parts
}

/// map 阶段的打包：普通单元沿用旧行为合并到同一块；超长单元先落盘当前块，再拆分。
fn pack_compaction_units(units: Vec<CompactionUnit>) -> Result<Vec<String>, String> {
    let mut chunks = Vec::new();
    let mut current = String::new();
    let mut current_chars = 0usize;
    for unit in units {
        let unit_chars = unit.text.chars().count();
        if unit_chars > COMPACTION_SOURCE_CHARS {
            if !current.is_empty() {
                chunks.push(std::mem::take(&mut current));
                current_chars = 0;
            }
            chunks.extend(split_compaction_unit(&unit));
            continue;
        }
        if current_chars > 0 && current_chars + unit_chars > COMPACTION_SOURCE_CHARS {
            chunks.push(std::mem::take(&mut current));
            current_chars = 0;
        }
        current.push_str(&unit.text);
        current_chars += unit_chars;
    }
    if !current.is_empty() {
        chunks.push(current);
    }
    Ok(chunks)
}

/// reduce 阶段的打包：任何超长单元都按 UTF-8 边界切分（不丢字符、不失败），
/// 保证手动压缩只要 provider 可用就一定能落地。
fn pack_compaction_sources(units: Vec<String>) -> Result<Vec<String>, String> {
    let mut chunks = Vec::new();
    let mut current = String::new();
    let mut current_chars = 0usize;
    for unit in units {
        let unit_chars = unit.chars().count();
        if unit_chars > COMPACTION_SOURCE_CHARS {
            if !current.is_empty() {
                chunks.push(std::mem::take(&mut current));
                current_chars = 0;
            }
            chunks.extend(split_compaction_text(&unit, COMPACTION_SOURCE_CHARS));
            continue;
        }
        if current_chars > 0 && current_chars + unit_chars > COMPACTION_SOURCE_CHARS {
            chunks.push(std::mem::take(&mut current));
            current_chars = 0;
        }
        current.push_str(&unit);
        current_chars += unit_chars;
    }
    if !current.is_empty() {
        chunks.push(current);
    }
    Ok(chunks)
}

/// 把一段超长文本按 UTF-8 字符边界切成多个 ≤ `max_chars` 的子块，每块带
/// PART 头；不省略任何字符。
fn split_compaction_text(text: &str, max_chars: usize) -> Vec<String> {
    let total = text.chars().count();
    let header_upper = "COMPACTION_PART 999999/999999:\n".chars().count();
    let body_budget = max_chars.saturating_sub(header_upper).max(1);
    let part_count = total.div_ceil(body_budget);
    let chars: Vec<char> = text.chars().collect();
    let mut parts = Vec::with_capacity(part_count);
    let mut offset = 0usize;
    for part_index in 1..=part_count {
        let take = body_budget.min(total - offset);
        let piece: String = chars[offset..offset + take].iter().collect();
        offset += take;
        parts.push(format!(
            "COMPACTION_PART {part_index}/{part_count}:\n{piece}"
        ));
    }
    parts
}

fn compaction_source_chunks(messages: &[Message]) -> Result<Vec<String>, String> {
    pack_compaction_units(compaction_units(messages)?)
}

async fn request_compaction_summary(
    provider: &dyn agent_contract::LlmProvider,
    model: &str,
    inference: &InferenceOptions,
    prompt: String,
) -> Result<String, String> {
    let prompt_chars = prompt.chars().count();
    if prompt_chars > COMPACTION_REQUEST_CHARS {
        return Err(format!(
            "手动压缩请求超过单次上限（{prompt_chars}/{COMPACTION_REQUEST_CHARS} 字符），本次未应用压缩"
        ));
    }
    let mut max_tokens = COMPACTION_SUMMARY_MAX_TOKENS;
    for attempt in 0..2 {
        let response = tokio::time::timeout(
            std::time::Duration::from_secs(120),
            provider.complete(CompletionRequest {
                model: model.to_string(),
                system: Some("你是精确的会话上下文压缩器。只返回结构化摘要。".to_string()),
                messages: vec![Message::user_text(prompt.clone())],
                tools: vec![],
                hosted_tools: vec![],
                max_tokens,
                temperature: Some(0.1),
                enable_caching: false,
                inference: inference.clone(),
            }),
        )
        .await
        .map_err(|_| "生成上下文摘要超时，请稍后重试".to_string())?
        .map_err(|error| format!("生成上下文摘要失败：{}", err_str(error)))?;
        if response.stop_reason == agent_contract::StopReason::MaxTokens && attempt == 0 {
            max_tokens /= 2;
            continue;
        }
        if response.stop_reason == agent_contract::StopReason::MaxTokens {
            return Err("上下文摘要未完整生成，请稍后重试".to_string());
        }
        if !matches!(
            response.stop_reason,
            agent_contract::StopReason::EndTurn | agent_contract::StopReason::StopSequence
        ) {
            return Err(format!(
                "上下文摘要异常结束（{:?}），本次未应用压缩",
                response.stop_reason
            ));
        }
        let summary = response.text();
        let summary = summary.trim();
        if summary.is_empty() {
            return Err("模型没有返回可用的上下文摘要".to_string());
        }
        let summary_chars = summary.chars().count();
        if summary_chars <= COMPACTION_SUMMARY_CHARS {
            return Ok(summary.to_string());
        }
        if attempt == 0 {
            max_tokens /= 2;
            continue;
        }
        // 最后兜底：带标记的有界截断，保证手动压缩仍然落地。
        tracing::warn!(
            summary_chars,
            "compaction summary exceeded the cap after retry; truncating with marker"
        );
        return Ok(format!(
            "[R-Code 已截断摘要尾部] {}",
            trim_chars(summary, COMPACTION_SUMMARY_CHARS)
        ));
    }
    Err("生成上下文摘要失败：重试未收敛".to_string())
}

/// Context compaction is a bounded evidence-preserving transformation, so an automatic
/// DeepSeek V4 session should not pay the full Pro reasoning latency for every map/reduce call.
/// Explicit user choices remain authoritative; only the local smart-balance state (empty or the
/// legacy `adaptive` marker) is translated to the model's cheapest supported native mode.
fn deepseek_fast_compaction_inference(
    provider: &agent_config::ProviderConfig,
    model: &str,
    configured: &InferenceOptions,
) -> InferenceOptions {
    if !is_deepseek_provider(provider)
        || !matches!(configured.thinking.as_deref(), None | Some("adaptive"))
        || configured.reasoning_effort.is_some()
    {
        return configured.clone();
    }

    let (thinking, reasoning_effort) = match model.trim().to_ascii_lowercase().as_str() {
        // Flash exposes a real low tier, which is a better fit for loss-aware summarization than
        // turning reasoning off completely.
        "deepseek-v4-flash" => (Some("enabled".to_string()), Some("low".to_string())),
        // Pro has no low tier. A synthetic `low` would be normalized back to high by the service,
        // so use the documented off mode for this bounded transformation instead.
        "deepseek-v4-pro" => (Some("disabled".to_string()), None),
        _ => return configured.clone(),
    };

    InferenceOptions {
        thinking,
        reasoning_effort,
        verbosity: configured.verbosity.clone(),
    }
}

async fn summarize_compaction_groups(
    provider: &dyn agent_contract::LlmProvider,
    model: &str,
    inference: &InferenceOptions,
    groups: Vec<String>,
    prompt_prefix: &str,
) -> Result<Vec<String>, String> {
    use futures::stream::{self, StreamExt};

    let mut indexed = stream::iter(groups.into_iter().enumerate().map(|(index, group)| {
        let prompt = format!("{prompt_prefix}\n\n{group}");
        async move {
            request_compaction_summary(provider, model, inference, prompt)
                .await
                .map(|summary| (index, summary))
        }
    }))
    .buffer_unordered(COMPACTION_SUMMARY_CONCURRENCY)
    .collect::<Vec<_>>()
    .await;
    let mut ordered = Vec::with_capacity(indexed.len());
    for result in indexed.drain(..) {
        ordered.push(result?);
    }
    ordered.sort_by_key(|(index, _)| *index);
    Ok(ordered.into_iter().map(|(_, summary)| summary).collect())
}

async fn summarize_compaction_history(
    provider: &dyn agent_contract::LlmProvider,
    model: &str,
    inference: &InferenceOptions,
    messages: &[Message],
    focus: Option<&str>,
) -> Result<String, String> {
    let chunks = compaction_source_chunks(messages)?;
    if chunks.is_empty() {
        return Err("没有可供压缩的会话内容".to_string());
    }
    let focus_line = focus
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(|value| format!("\n用户特别要求保留：{}", trim_chars(value, 2_000)))
        .unwrap_or_default();
    let chunk_count = chunks.len();
    let map_prompt = format!(
        "把下面较早会话的一个完整分块压缩成一份能让另一个编码 Agent 无缝继续工作的中文局部摘要（本次共 {chunk_count} 块）。\
必须保留这一块中的：用户目标与约束、已经确认的决定、重要文件/符号、已做修改、命令与验证结果、错误及根因、未完成事项，以及完整的工具证据。\
删除寒暄、重复过程和无结论的尝试。不要编造，不要写开场白。{focus_line}"
    );
    let mut summaries =
        summarize_compaction_groups(provider, model, inference, chunks, &map_prompt).await?;

    let mut round = 1usize;
    while summaries.len() > 1 {
        let before = summaries.len();
        let units = summaries
            .into_iter()
            .enumerate()
            .map(|(index, summary)| format!("PART {}:\n{}\n\n", index + 1, summary))
            .collect::<Vec<_>>();
        let groups = pack_compaction_sources(units)?;
        let group_count = groups.len();
        let reduce_prompt = format!(
            "合并下面第 {round} 轮的一组局部摘要（本轮共 {group_count} 组）。每个 PART 都来自不同的原始会话块，必须全部纳入。\
去重但不要丢失用户约束、决定、工具证据、文件/符号、修改、验证、错误根因和未完成事项。不要编造，只返回结构化中文摘要。{focus_line}"
        );
        let reduced =
            summarize_compaction_groups(provider, model, inference, groups, &reduce_prompt).await?;
        if reduced.len() >= before {
            return Err("上下文摘要无法在输入上限内收敛，本次未应用压缩".to_string());
        }
        summaries = reduced;
        round += 1;
    }
    summaries
        .pop()
        .ok_or_else(|| "模型没有返回可用的上下文摘要".to_string())
}

fn compacted_working_set(history: &[Message], summary: &str) -> Vec<Message> {
    if history.len() < COMPACTION_MIN_MESSAGES {
        return history.to_vec();
    }
    let recent_start = manual_compaction_recent_start(history);
    let mut result = history[..COMPACTION_KEEP_FIRST].to_vec();
    // 摘要是宿主注入的 continuation checkpoint，不是模型刚输出的 Assistant。
    // 用 User 角色承载，避免与 recent tail 的首条 Assistant 相邻而破坏严格协议。
    result.push(Message::user_text(format!(
        "[R-Code 上下文摘要]\n{}",
        summary.trim()
    )));
    result.extend_from_slice(&history[recent_start..]);
    result
}

fn manual_messages_form_tool_pair(call: &Message, result: &Message) -> bool {
    let call_ids = call
        .content
        .iter()
        .filter_map(ContentBlock::tool_id)
        .collect::<HashSet<_>>();
    !call_ids.is_empty()
        && result
            .content
            .iter()
            .filter_map(ContentBlock::tool_use_id)
            .any(|result_id| call_ids.contains(result_id))
}

fn manual_compaction_recent_start(history: &[Message]) -> usize {
    let mut recent_start = history.len().saturating_sub(COMPACTION_KEEP_RECENT);
    if recent_start > 0
        && manual_messages_form_tool_pair(&history[recent_start - 1], &history[recent_start])
    {
        recent_start -= 1;
    }
    recent_start
}

/// 压缩当前分支的模型工作集，同时保留完整可见聊天与审计记录。
pub async fn task_compact_context(
    state: &CommandState,
    task_id: &str,
    focus: Option<&str>,
) -> Result<ContextCompactionResult, String> {
    let task = TaskRepository::new(&state.db)
        .get(task_id)
        .map_err(err_str)?
        .ok_or_else(|| format!("task not found: {task_id}"))?;
    if task.state == TaskState::Archived {
        return Err("会话已归档，不能压缩上下文".to_string());
    }

    let task_agent = state.agent.bridge_for(task_id).await;
    {
        let bridge = task_agent.lock().await;
        if task_has_active_main_run(&state.db, task_id, &bridge)? {
            return Err("当前运行尚未结束，请先停止或等待完成后再压缩上下文".to_string());
        }
    }

    let branch = SessionBranchRepository::new(&state.db)
        .ensure_active(task_id)
        .map_err(err_str)?;
    ensure_session_log(
        &state.session_store,
        &state.sessions_dir,
        &branch.storage_id,
    )
    .await?;
    let history = state
        .session_store
        .load(&branch.storage_id)
        .await
        .map_err(err_str)?;
    let before_messages = history.messages.len();
    if before_messages < COMPACTION_MIN_MESSAGES {
        return Ok(ContextCompactionResult {
            compacted: false,
            before_messages,
            after_messages: before_messages,
        });
    }

    let settings = SettingsService::new(state.config_dir.clone());
    let config = settings.load_global_unvalidated().map_err(err_str)?;
    let provider_name = task
        .provider_name
        .as_deref()
        .map(str::trim)
        .filter(|name| !name.is_empty())
        .unwrap_or(config.default_provider.as_str());
    let provider_config = config
        .providers
        .get(provider_name)
        .ok_or_else(|| format!("未找到模型服务“{provider_name}”，请前往设置完成配置"))?;
    if let Some(problem) = provider_readiness_error(provider_name, provider_config) {
        return Err(format!("模型服务“{provider_name}”尚未就绪：{problem}"));
    }
    let provider =
        agent_llm::create_provider(build_provider_config(provider_name, provider_config))
            .map_err(err_str)?;

    let recent_start = manual_compaction_recent_start(&history.messages);
    let to_summarize = &history.messages[COMPACTION_KEEP_FIRST..recent_start];
    let focus = focus
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(|value| trim_chars(value, 2_000));
    let model = task
        .model
        .as_deref()
        .filter(|value| !value.trim().is_empty())
        .unwrap_or(provider_config.model.as_str())
        .to_string();
    let compaction_inference =
        deepseek_fast_compaction_inference(provider_config, &model, &task.inference);
    let summary = summarize_compaction_history(
        provider.as_ref(),
        &model,
        &compaction_inference,
        to_summarize,
        focus.as_deref(),
    )
    .await?;
    let compacted = compacted_working_set(&history.messages, &summary);

    // 摘要生成期间可能有另一入口启动了运行；写快照前再次检查并持锁，避免新消息
    // 落在快照之后却被旧摘要覆盖。
    let mut bridge = task_agent.lock().await;
    if task_has_active_main_run(&state.db, task_id, &bridge)? {
        return Err("摘要生成期间会话开始了新的运行，本次未应用压缩".to_string());
    }
    let current_branch = SessionBranchRepository::new(&state.db)
        .ensure_active(task_id)
        .map_err(err_str)?;
    if current_branch.id != branch.id || current_branch.storage_id != branch.storage_id {
        return Err("摘要生成期间会话分支已变化，本次未应用压缩".to_string());
    }
    state
        .session_store
        .append(
            &branch.storage_id,
            SessionEvent::ModelProjection {
                messages: Some(compacted.clone()),
            },
        )
        .await
        .map_err(err_str)?;
    state
        .session_store
        .append(
            &branch.storage_id,
            SessionEvent::System {
                event: "r_code_context_compacted".to_string(),
                data: serde_json::json!({
                    "before_messages": before_messages,
                    "after_messages": compacted.len(),
                }),
            },
        )
        .await
        .map_err(err_str)?;
    bridge.sessions.remove(task_id);
    drop(bridge);
    TaskEventStore::new(&state.db)
        .append_for_branch(task_id, &branch.id, TaskEventType::System)
        .map_err(err_str)?;

    Ok(ContextCompactionResult {
        compacted: true,
        before_messages,
        after_messages: compacted.len(),
    })
}

pub async fn task_list(
    state: &CommandState,
    workspace_path: Option<&str>,
    include_archived: bool,
) -> Result<Vec<Task>, String> {
    TaskRepository::new(&state.db)
        .list(workspace_path, None, include_archived)
        .map_err(err_str)
}

/// 归档一个已经停止的会话。运行中的会话必须先中止，避免后台运行成为孤儿。
pub async fn task_archive(state: &CommandState, task_id: &str) -> Result<Task, String> {
    let repo = TaskRepository::new(&state.db);
    let task = repo
        .get(task_id)
        .map_err(err_str)?
        .ok_or_else(|| format!("task not found: {task_id}"))?;
    if task.state == TaskState::Archived {
        return Ok(task);
    }
    if matches!(task.state, TaskState::Exploring | TaskState::InProgress) {
        return Err("会话仍在运行，请先停止后归档".to_string());
    }

    let task_agent = state.agent.bridge_for(task_id).await;
    let mut bridge = task_agent.lock().await;
    if task_has_active_main_run(&state.db, task_id, &bridge)? {
        return Err("会话仍在运行，请先停止后归档".to_string());
    }
    repo.update_state(task_id, TaskState::Archived)
        .map_err(err_str)?;
    state.codex_app_server.invalidate(task_id).await;
    // 归档会话不再保留可继续运行的内存映射；持久化历史仍保留给审计与恢复。
    bridge.sessions.remove(task_id);
    drop(bridge);
    state.agent.remove(task_id).await;

    repo.get(task_id)
        .map_err(err_str)?
        .ok_or_else(|| format!("task not found after archive: {task_id}"))
}

/// 将归档会话还原为空闲状态，使其重新出现在项目任务与对话列表中。
pub async fn task_restore(state: &CommandState, task_id: &str) -> Result<Task, String> {
    let repo = TaskRepository::new(&state.db);
    let task = repo
        .get(task_id)
        .map_err(err_str)?
        .ok_or_else(|| format!("task not found: {task_id}"))?;
    if task.state != TaskState::Archived {
        return Ok(task);
    }

    repo.update_state(task_id, TaskState::Idle)
        .map_err(err_str)?;
    repo.get(task_id)
        .map_err(err_str)?
        .ok_or_else(|| format!("task not found after restore: {task_id}"))
}

fn remove_task_session_logs(sessions_dir: &Path, task_id: &str, storage_ids: &HashSet<String>) {
    // 只枚举 R-Code 自己的会话目录，不接受调用方提供的删除目标。工作区目录永远
    // 不会进入这条路径。
    if let Ok(entries) = std::fs::read_dir(sessions_dir) {
        for entry in entries.flatten() {
            let path = entry.path();
            let file_name = entry.file_name();
            let Some(file_name) = file_name.to_str() else {
                continue;
            };
            let storage_match = storage_ids
                .iter()
                .any(|storage_id| file_name == format!("{storage_id}.jsonl"));
            let task_prefix_match = file_name.ends_with(".jsonl")
                && (file_name == format!("{task_id}.jsonl")
                    || file_name.starts_with(&format!("{task_id}--")));
            if (storage_match || task_prefix_match) && path.is_file() {
                if let Err(error) = std::fs::remove_file(&path) {
                    tracing::warn!(task_id, file = %path.display(), %error, "failed to remove deleted task session log");
                }
            }
        }
    }
    remove_task_attachment_previews(sessions_dir, task_id);
}

/// 删除任务的本机 OCR 原图预览目录（`{app_data}/attachments/{task_id}`）。
///
/// 与会话日志同生命周期：任务删除或工作区解绑后不再保留可预览的原图副本。
/// 目录缺失视为已清理；任务标识不是安全路径段时拒绝删除，防止越界。
fn remove_task_attachment_previews(sessions_dir: &Path, task_id: &str) {
    if !is_safe_path_segment(task_id) {
        tracing::warn!(
            task_id,
            "refused to remove attachment previews for unsafe task id"
        );
        return;
    }
    let Some(root) = sessions_dir.parent() else {
        return;
    };
    let directory = root.join("attachments").join(task_id);
    if let Err(error) = std::fs::remove_dir_all(&directory) {
        if error.kind() != std::io::ErrorKind::NotFound {
            tracing::warn!(task_id, dir = %directory.display(), %error, "failed to remove deleted task attachment previews");
        }
    }
}

/// 永久删除一个已经停止的会话及其 R-Code 审计数据。
///
/// 工作区和其中的文件不属于会话存储，永远不会在这里删除。运行中的会话必须先停止，
/// 防止后台进程继续向已经被级联清理的记录写入。
pub async fn task_delete(state: &CommandState, task_id: &str) -> Result<(), String> {
    let repo = TaskRepository::new(&state.db);
    let task = repo
        .get(task_id)
        .map_err(err_str)?
        .ok_or_else(|| format!("task not found: {task_id}"))?;
    if matches!(task.state, TaskState::Exploring | TaskState::InProgress) {
        return Err("会话仍在运行，请先停止后删除".to_string());
    }

    let storage_ids = SessionBranchRepository::new(&state.db)
        .list_by_task(task_id)
        .map_err(err_str)?
        .into_iter()
        .map(|branch| branch.storage_id)
        .collect::<HashSet<_>>();

    let task_agent = state.agent.bridge_for(task_id).await;
    let mut bridge = task_agent.lock().await;
    if task_has_active_main_run(&state.db, task_id, &bridge)? {
        return Err("会话仍在运行，请先停止后删除".to_string());
    }
    if !repo
        .delete(
            task_id,
            &state.blobs_dir,
            state.plan_store.projection_root(),
        )
        .map_err(err_str)?
    {
        return Err(format!("task not found: {task_id}"));
    }
    state.codex_app_server.invalidate(task_id).await;
    bridge.sessions.remove(task_id);
    drop(bridge);
    state.agent.remove(task_id).await;
    let terminal_ids = {
        let mut terminal_owners = state
            .terminal_owners
            .lock()
            .map_err(|_| "terminal ownership state is unavailable".to_string())?;
        let terminal_ids = terminal_owners
            .iter()
            .filter(|(_, owner_task_id)| *owner_task_id == task_id)
            .map(|(terminal_id, _)| terminal_id.clone())
            .collect::<Vec<_>>();
        terminal_owners.retain(|_, owner_task_id| owner_task_id != task_id);
        terminal_ids
    };
    terminate_terminals(state, terminal_ids).await;

    // JSONL 不在 SQLite 事务中；数据库删除成功后做幂等的最佳努力清理。
    // 同时按 task 前缀覆盖旧主分支和外部子代理日志，绝不触碰工作区目录。
    remove_task_session_logs(&state.sessions_dir, task_id, &storage_ids);
    Ok(())
}

/// 将空闲会话一次性附加到已打开的工作区。
///
/// 工作区一旦附加即可公开受 PathGuard 限制的本地工具；工具调用的审批策略来自
/// 工作区持久化的项目权限模式。已绑定会话只允许同路径幂等刷新，不能改绑或解绑。
pub async fn task_set_workspace(
    state: &CommandState,
    task_id: &str,
    workspace_path: Option<&str>,
) -> Result<Task, String> {
    let requested_workspace = workspace_path
        .filter(|path| !path.trim().is_empty())
        .map(|path| workspace_root(state, path).map(|root| (path.to_string(), root)))
        .transpose()?;

    let repo = TaskRepository::new(&state.db);
    let task_agent = state.agent.bridge_for(task_id).await;
    let mut bridge = task_agent.lock().await;
    let task = repo
        .get(task_id)
        .map_err(err_str)?
        .ok_or_else(|| format!("task not found: {task_id}"))?;
    if task.state == TaskState::Archived {
        return Err("会话已归档，不能再修改工作区".to_string());
    }
    if matches!(task.state, TaskState::Exploring | TaskState::InProgress)
        || task_has_active_main_run(&state.db, task_id, &bridge)?
    {
        return Err("当前运行尚未结束，不能在执行期间附加工作区".to_string());
    }

    let path = match (task.workspace_path.as_deref(), requested_workspace.as_ref()) {
        (Some(current), Some((_, requested_root)))
            if workspace_binding_matches_root(current, requested_root) =>
        {
            Some(current.to_string())
        }
        (Some(_), _) => return Err("此会话已绑定项目；如需使用其他项目，请新建对话".to_string()),
        (None, None) => return Ok(task),
        (None, Some((requested, _))) => Some(requested.clone()),
    };

    let mut task = task;
    task.updated_at = repo
        .set_workspace_path(task_id, path.as_deref())
        .map_err(err_str)?;
    task.workspace_path = path;
    state.codex_app_server.invalidate(task_id).await;
    // 与 provider/model 切换保持同一个提交边界：数据库成功后只丢弃缓存映射，
    // 下一轮会从持久化历史与新工作区重建。这里没有“DB 已改、runtime 更新失败”的假失败。
    bridge.sessions.remove(task_id);
    Ok(task)
}

/// 从尚未登记的本地路径附加会话。任务不可附加时，必须在 workspace
/// 写入之前失败，避免产生“左栏已添加、会话仍未绑定”的半成功状态。
pub async fn task_attach_workspace(
    state: &CommandState,
    task_id: &str,
    workspace_path: &Path,
) -> Result<Task, String> {
    let canonical = canonical_workspace_path(workspace_path)?;
    let canonical_path = canonical.display().to_string();
    let repo = TaskRepository::new(&state.db);
    let task_agent = state.agent.bridge_for(task_id).await;
    let mut bridge = task_agent.lock().await;
    let task = repo
        .get(task_id)
        .map_err(err_str)?
        .ok_or_else(|| format!("task not found: {task_id}"))?;
    if task.state == TaskState::Archived {
        return Err("会话已归档，不能再附加工作区".to_string());
    }
    if matches!(task.state, TaskState::Exploring | TaskState::InProgress)
        || task_has_active_main_run(&state.db, task_id, &bridge)?
    {
        return Err("当前运行尚未结束，不能在执行期间附加工作区".to_string());
    }
    match task.workspace_path.as_deref() {
        Some(current) if workspace_binding_matches_root(current, &canonical) => return Ok(task),
        Some(_) => return Err("此会话已绑定项目；如需使用其他项目，请新建对话".to_string()),
        None => {}
    }

    let mut task = task;
    let display_name = canonical
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("workspace");
    let (_, updated_at) = WorkspaceService::new(&state.db)
        .attach_task_once(task_id, &canonical_path, display_name)
        .map_err(err_str)?;
    task.updated_at = updated_at;
    task.workspace_path = Some(canonical_path);
    state.codex_app_server.invalidate(task_id).await;
    bridge.sessions.remove(task_id);
    Ok(task)
}

/// 为一个空闲会话切换绑定的模型服务。
///
/// 运行中的 provider、模型和上下文必须是同一份快照，故禁止中途切换；成功后只清除
/// 本会话的内存 runtime 映射，下一次运行将以新服务和完整持久化历史重新建立。
pub async fn task_set_provider(
    state: &CommandState,
    task_id: &str,
    provider_name: &str,
) -> Result<Task, String> {
    let provider_name = validate_selected_provider(state, Some(provider_name))?
        .ok_or_else(|| "请选择模型服务".to_string())?;
    let repo = TaskRepository::new(&state.db);
    let task_agent = state.agent.bridge_for(task_id).await;
    let mut bridge = task_agent.lock().await;
    let task = repo
        .get(task_id)
        .map_err(err_str)?
        .ok_or_else(|| format!("task not found: {task_id}"))?;
    if task.state == TaskState::Archived {
        return Err("会话已归档，不能再切换模型服务".to_string());
    }
    if task_has_active_main_run(&state.db, task_id, &bridge)? {
        return Err("当前运行尚未结束，不能在执行期间切换模型服务配置".to_string());
    }
    repo.set_provider_name(task_id, Some(&provider_name))
        .map_err(err_str)?;
    // 模型名隶属于具体服务，换服务后旧的覆盖值必然无效，一并清除。
    repo.set_model(task_id, None).map_err(err_str)?;
    repo.set_inference(task_id, &InferenceOptions::default())
        .map_err(err_str)?;
    bridge.sessions.remove(task_id);
    drop(bridge);

    repo.get(task_id)
        .map_err(err_str)?
        .ok_or_else(|| format!("task not found after provider update: {task_id}"))
}

/// 切换空闲会话的主 Agent。选择写入任务本身，并清除仅属于 R-Code provider 的
/// 内存 session；聊天 JSONL、分支和审计记录保持不变。
pub async fn task_set_agent_engine(
    state: &CommandState,
    task_id: &str,
    agent_engine: &str,
) -> Result<Task, String> {
    let agent_engine = AgentEngine::try_from_str(agent_engine.trim())
        .ok_or_else(|| "主 Agent 只支持 r_code 或 codex".to_string())?;
    let repo = TaskRepository::new(&state.db);
    let task_agent = state.agent.bridge_for(task_id).await;
    let mut bridge = task_agent.lock().await;
    let task = repo
        .get(task_id)
        .map_err(err_str)?
        .ok_or_else(|| format!("task not found: {task_id}"))?;
    if task.state == TaskState::Archived {
        return Err("会话已归档，不能再切换主 Agent".to_string());
    }
    if agent_engine == AgentEngine::Codex && task.mode == TaskMode::Plan {
        return Err(
            "Plan 模式仅支持 R-Code 内置 Agent；请先退出 Plan 模式再切换 Codex CLI".to_string(),
        );
    }
    if task_has_active_main_run(&state.db, task_id, &bridge)? {
        return Err("当前运行尚未结束，不能在执行期间切换主 Agent".to_string());
    }
    repo.set_agent_engine(task_id, agent_engine)
        .map_err(err_str)?;
    state.codex_app_server.invalidate(task_id).await;
    bridge.sessions.remove(task_id);
    drop(bridge);

    repo.get(task_id)
        .map_err(err_str)?
        .ok_or_else(|| format!("task not found after agent update: {task_id}"))
}

/// 为一个空闲会话切换具体模型（仍属于当前绑定的模型服务）。
///
/// 与 `task_set_provider` 同样的约束：运行中不允许切换，且必须清掉内存里的
/// runtime session —— 已建立的 SessionState 会把旧模型一直用到会话结束。
/// 传入空字符串表示清除覆盖，回退到该服务在设置里配置的默认模型。
pub async fn task_set_model(
    state: &CommandState,
    task_id: &str,
    model: Option<&str>,
) -> Result<Task, String> {
    let model = model.map(str::trim).filter(|value| !value.is_empty());
    if let Some(value) = model {
        if value.len() > 200 {
            return Err("模型名过长".to_string());
        }
    }

    let repo = TaskRepository::new(&state.db);
    let task_agent = state.agent.bridge_for(task_id).await;
    let mut bridge = task_agent.lock().await;
    let task = repo
        .get(task_id)
        .map_err(err_str)?
        .ok_or_else(|| format!("task not found: {task_id}"))?;
    if task.state == TaskState::Archived {
        return Err("会话已归档，不能再切换模型".to_string());
    }
    if task_has_active_main_run(&state.db, task_id, &bridge)? {
        return Err("当前运行尚未结束，不能在执行期间切换模型".to_string());
    }
    repo.set_model(task_id, model).map_err(err_str)?;
    // 推理参数属于具体模型，切换后回到服务默认，避免把 xhigh 等值带给不支持的模型。
    repo.set_inference(task_id, &InferenceOptions::default())
        .map_err(err_str)?;
    bridge.sessions.remove(task_id);
    drop(bridge);

    repo.get(task_id)
        .map_err(err_str)?
        .ok_or_else(|| format!("task not found after model update: {task_id}"))
}

fn validated_inference(mut inference: InferenceOptions) -> Result<InferenceOptions, String> {
    fn normalize(value: Option<String>) -> Option<String> {
        value
            .map(|item| item.trim().to_ascii_lowercase())
            .filter(|item| !item.is_empty())
    }
    inference.thinking = normalize(inference.thinking);
    inference.reasoning_effort = normalize(inference.reasoning_effort);
    inference.verbosity = normalize(inference.verbosity);

    if inference
        .thinking
        .as_deref()
        .is_some_and(|value| !matches!(value, "enabled" | "disabled" | "adaptive"))
    {
        return Err("thinking 只支持 enabled、disabled 或 adaptive".to_string());
    }
    if inference.reasoning_effort.as_deref().is_some_and(|value| {
        !matches!(
            value,
            "none" | "minimal" | "low" | "medium" | "high" | "xhigh" | "max" | "ultra"
        )
    }) {
        return Err("不支持的推理强度".to_string());
    }
    if inference
        .verbosity
        .as_deref()
        .is_some_and(|value| !matches!(value, "low" | "medium" | "high"))
    {
        return Err("输出详略只支持 low、medium 或 high".to_string());
    }
    Ok(inference)
}

/// 更新空闲会话的模型专属推理参数。未提供的字段继续使用服务默认值。
pub async fn task_set_inference(
    state: &CommandState,
    task_id: &str,
    inference: InferenceOptions,
) -> Result<Task, String> {
    let inference = validated_inference(inference)?;
    let repo = TaskRepository::new(&state.db);
    let task_agent = state.agent.bridge_for(task_id).await;
    let mut bridge = task_agent.lock().await;
    let task = repo
        .get(task_id)
        .map_err(err_str)?
        .ok_or_else(|| format!("task not found: {task_id}"))?;
    if task.state == TaskState::Archived {
        return Err("会话已归档，不能再修改模型配置".to_string());
    }
    if task_has_active_main_run(&state.db, task_id, &bridge)? {
        return Err("当前运行尚未结束，不能在执行期间修改模型配置".to_string());
    }
    repo.set_inference(task_id, &inference).map_err(err_str)?;
    bridge.sessions.remove(task_id);
    drop(bridge);

    repo.get(task_id)
        .map_err(err_str)?
        .ok_or_else(|| format!("task not found after inference update: {task_id}"))
}

fn bounded_status_count(count: usize) -> u32 {
    u32::try_from(count).unwrap_or(u32::MAX)
}

async fn pending_task_question_count(state: &CommandState, task_id: &str) -> Result<u32, String> {
    let plan_questions = state
        .plan_store
        .current_for_task(task_id)
        .map_err(err_str)?
        .and_then(|view| view.pending_question_set)
        .map(|set| bounded_status_count(set.questions.len()))
        .unwrap_or_default();

    // Codex requestUserInput cards are restored from their non-secret JSONL markers. Reuse the
    // same reconstruction path as the Room so expired requests cannot keep a phantom attention
    // state. A damaged/unreadable transcript must not make the otherwise available task detail
    // endpoint disappear; the Room's dedicated history request will still surface that error.
    let codex_questions = match session_messages(state, task_id).await {
        Ok(messages) => bounded_status_count(
            messages
                .iter()
                .filter(|message| {
                    message.kind == "codex_question"
                        && message.output_json.as_deref().is_some_and(|payload| {
                            serde_json::from_str::<serde_json::Value>(payload)
                                .ok()
                                .is_some_and(|value| {
                                    value.get("state").and_then(serde_json::Value::as_str)
                                        == Some("pending")
                                })
                        })
                })
                .count(),
        ),
        Err(error) => {
            tracing::warn!(task_id, %error, "task status could not inspect Codex question markers");
            0
        }
    };
    Ok(plan_questions.saturating_add(codex_questions))
}

async fn project_host_task_status(
    state: &CommandState,
    task: &Task,
    runs: &[AgentRun],
    queued_messages: &[QueuedMessage],
    approvals: &[PermissionRequest],
    latest_verification: Option<&VerificationRecord>,
) -> Result<TaskStatusView, String> {
    let pending_question_count = if task.state == TaskState::Archived {
        0
    } else {
        pending_task_question_count(state, &task.id).await?
    };
    let workspace_binding_invalid = match resolve_task_workspace_binding(&state.db, task) {
        Ok(_) => false,
        Err(error @ ProductError::DatabaseError(_)) => return Err(err_str(error)),
        Err(_) => true,
    };
    let unread_count = NotificationRepository::new(&state.db)
        .unread_count_for_task(&task.id)
        .map_err(err_str)?;
    Ok(project_task_status(TaskStatusProjectionInput {
        task,
        runs,
        queued_messages,
        approvals,
        pending_question_count,
        latest_verification,
        workspace_binding_invalid,
        unread_count,
    }))
}

pub async fn task_detail(state: &CommandState, task_id: &str) -> Result<TaskDetail, String> {
    let task = TaskRepository::new(&state.db)
        .get(task_id)
        .map_err(err_str)?
        .ok_or_else(|| format!("task not found: {task_id}"))?;
    let active_branch = SessionBranchRepository::new(&state.db)
        .ensure_active(task_id)
        .map_err(err_str)?;
    let branches = SessionBranchRepository::new(&state.db)
        .list_by_task(task_id)
        .map_err(err_str)?;

    let runs = AgentRunRepository::new(&state.db)
        .list_by_task_branch(task_id, &active_branch.id)
        .map_err(err_str)?;

    let events = TaskEventStore::new(&state.db)
        .list_by_task_branch(task_id, &active_branch.id, Some(400), None)
        .map_err(err_str)?;

    let changes = changes_list(state, task_id).await?;

    let permissions = state.permission_engine.pending_for_task(task_id).await;

    let verifications = VerificationService::new(&state.db, state.blobs_dir.clone())
        .list_for_task(task_id)
        .await
        .map_err(err_str)?;
    let queued_messages = QueuedMessageRepository::new(&state.db)
        .list_pending(task_id, &active_branch.id)
        .map_err(err_str)?;

    let pending_plan_entry_offer =
        crate::plan_entry_commands::plan_entry_offer_view_for_task(&state.planning, task_id)
            .map_err(err_str)?;
    let latest_verification = verifications.iter().max_by_key(|record| record.started_at);
    let status = project_host_task_status(
        state,
        &task,
        &runs,
        &queued_messages,
        &permissions,
        latest_verification,
    )
    .await?;
    Ok(TaskDetail {
        task,
        status,
        active_branch,
        branches,
        runs,
        events,
        changes,
        permissions,
        verifications,
        queued_messages,
        pending_plan_entry_offer,
    })
}

/// 单次读取多个任务详情，供项目 / 活动页避免为每个任务走一次 WebView IPC。
pub async fn task_detail_batch(
    state: &CommandState,
    task_ids: &[String],
) -> Result<TaskDetailBatch, String> {
    const MAX_BATCH_SIZE: usize = 80;
    let mut unique_ids = Vec::new();
    for task_id in task_ids {
        if task_id.trim().is_empty() || unique_ids.iter().any(|known| known == task_id) {
            continue;
        }
        unique_ids.push(task_id.clone());
    }
    if unique_ids.len() > MAX_BATCH_SIZE {
        return Err(format!("一次最多读取 {MAX_BATCH_SIZE} 个任务详情"));
    }

    let mut details = Vec::with_capacity(unique_ids.len());
    for task_id in unique_ids {
        details.push(task_detail(state, &task_id).await?);
    }
    Ok(TaskDetailBatch { details })
}

fn display_task_title(task: &Task) -> String {
    let title = task.title.trim();
    if !title.is_empty() {
        return title.to_string();
    }
    let goal = task.goal.trim();
    if !goal.is_empty() {
        return goal.to_string();
    }
    "未命名任务".to_string()
}

fn summarize_changes(changes: &[FileChange]) -> DashboardChangeSummary {
    let mut summary = DashboardChangeSummary {
        files: changes.len() as u32,
        ..DashboardChangeSummary::default()
    };
    for change in changes {
        match change.change_type {
            FileChangeType::Create => summary.created += 1,
            FileChangeType::Modify => summary.modified += 1,
            FileChangeType::Delete => summary.removed += 1,
            FileChangeType::Rename => summary.renamed += 1,
        }
    }
    summary
}

fn is_live_dashboard_task(task: &Task, runs: &[AgentRun]) -> bool {
    matches!(task.state, TaskState::Exploring | TaskState::InProgress)
        || runs
            .iter()
            .any(|run| run.ended_at.is_none() && run.model != VERIFICATION_PLACEHOLDER_MODEL)
}

fn current_dashboard_run(runs: &[AgentRun]) -> Option<AgentRun> {
    runs.iter()
        .find(|run| run.ended_at.is_none() && run.model != VERIFICATION_PLACEHOLDER_MODEL)
        .cloned()
        .or_else(|| {
            runs.iter()
                .find(|run| {
                    run.agent_kind == AgentKind::Main && run.model != VERIFICATION_PLACEHOLDER_MODEL
                })
                .cloned()
        })
        .or_else(|| runs.first().cloned())
}

fn dashboard_agent_label(run: Option<&AgentRun>) -> String {
    match run {
        Some(run)
            if run
                .agent_label
                .as_deref()
                .is_some_and(|label| !label.trim().is_empty()) =>
        {
            run.agent_label.clone().unwrap_or_default()
        }
        Some(run) if run.agent_kind == AgentKind::Subagent => "子代理".to_string(),
        _ => "主代理".to_string(),
    }
}

fn dashboard_activity(
    task: &Task,
    permissions: &[PermissionRequest],
    run: Option<&AgentRun>,
) -> String {
    if let Some(permission) = permissions.first() {
        return format!("等待授权 · {}", permission.tool_name);
    }
    if let Some(summary) = run.and_then(|item| item.summary.as_deref()) {
        if !summary.trim().is_empty() {
            return summary.trim().to_string();
        }
    }
    match task.state {
        TaskState::Exploring => "梳理代码与执行路径".to_string(),
        TaskState::InProgress => "正在推进任务".to_string(),
        TaskState::ReviewReady => "变更已准备好审查".to_string(),
        TaskState::Interrupted => "任务已停止".to_string(),
        TaskState::Idle => "任务已完成".to_string(),
        TaskState::Archived => "会话已归档".to_string(),
    }
}

fn dashboard_task_rank(summary: &DashboardTaskSummary) -> u8 {
    if summary.pending_permission_count > 0 {
        0
    } else if summary.task.state == TaskState::ReviewReady {
        1
    } else if summary
        .active_run
        .as_ref()
        .is_some_and(|run| run.ended_at.is_none())
        || matches!(
            summary.task.state,
            TaskState::Exploring | TaskState::InProgress
        )
    {
        2
    } else if summary.task.state == TaskState::Interrupted {
        3
    } else if summary.task.state == TaskState::Idle {
        4
    } else {
        5
    }
}

/// 获取一个工作区的仪表盘聚合数据。
///
/// 所有统计口径在同一后端时刻计算，前端不再根据多轮轮询的详情缓存拼装数量。
pub async fn workspace_dashboard(
    state: &CommandState,
    workspace_path: &str,
) -> Result<WorkspaceDashboard, String> {
    let workspace = WorkspaceService::new(&state.db)
        .get(workspace_path)
        .map_err(err_str)?
        .ok_or_else(|| {
            "workspace is not open; choose the folder before viewing its dashboard".to_string()
        })?;
    let tasks = TaskRepository::new(&state.db)
        .list(Some(&workspace.canonical_path), None, true)
        .map_err(err_str)?;

    let now = chrono::Utc::now();
    let runs = AgentRunRepository::new(&state.db);
    let change_service = ChangeService::new(&state.db, state.blobs_dir.clone());
    let verification_service = VerificationService::new(&state.db, state.blobs_dir.clone());
    let mut metrics = WorkspaceDashboardMetrics::default();
    let mut summaries = Vec::with_capacity(tasks.len());
    let mut attention = Vec::new();
    let mut archived = Vec::new();

    for task in tasks {
        if task.state == TaskState::Archived {
            metrics.archived_task_count += 1;
            archived.push(task);
            continue;
        }
        metrics.task_count += 1;
        let task_runs = runs.list_by_task(&task.id).map_err(err_str)?;
        let active_run = current_dashboard_run(&task_runs);
        let pending_permissions = state.permission_engine.pending_for_task(&task.id).await;
        let changes = change_service
            .list_changes(&task.id)
            .await
            .map_err(err_str)?;
        let verifications = verification_service
            .list_for_task(&task.id)
            .await
            .map_err(err_str)?;
        let latest_verification = verifications
            .iter()
            .max_by_key(|record| record.started_at)
            .cloned();
        let active_branch = SessionBranchRepository::new(&state.db)
            .ensure_active(&task.id)
            .map_err(err_str)?;
        let queued_messages = QueuedMessageRepository::new(&state.db)
            .list_pending(&task.id, &active_branch.id)
            .map_err(err_str)?;
        let status = project_host_task_status(
            state,
            &task,
            &task_runs,
            &queued_messages,
            &pending_permissions,
            latest_verification.as_ref(),
        )
        .await?;
        let live = is_live_dashboard_task(&task, &task_runs);

        metrics.pending_permission_count += pending_permissions.len() as u32;
        if task.state == TaskState::ReviewReady {
            metrics.review_ready_count += 1;
        }
        // 与旧 UI 保持一致：正在等用户授权的任务优先归入“待处理”，不重复记到运行中。
        if live && pending_permissions.is_empty() {
            metrics.running_task_count += 1;
        }
        metrics.active_subagent_count += task_runs
            .iter()
            .filter(|run| run.agent_kind == AgentKind::Subagent && run.ended_at.is_none())
            .count() as u32;
        for permission in &pending_permissions {
            attention.push(DashboardAttentionItem {
                kind: DashboardAttentionKind::Permission,
                task: task.clone(),
                permission: Some(permission.clone()),
                since: permission.created_at,
            });
        }
        if task.state == TaskState::ReviewReady {
            attention.push(DashboardAttentionItem {
                kind: DashboardAttentionKind::ReviewReady,
                task: task.clone(),
                permission: None,
                since: task.updated_at,
            });
        }

        let summary = DashboardTaskSummary {
            activity: dashboard_activity(&task, &pending_permissions, active_run.as_ref()),
            agent_label: dashboard_agent_label(active_run.as_ref()),
            pending_permission_count: pending_permissions.len() as u32,
            change_summary: summarize_changes(&changes),
            latest_verification,
            active_run,
            status,
            task,
        };
        summaries.push(summary);
    }

    summaries.sort_by(|left, right| {
        dashboard_task_rank(left)
            .cmp(&dashboard_task_rank(right))
            .then_with(|| right.task.updated_at.cmp(&left.task.updated_at))
    });
    attention.sort_by_key(|item| item.since);
    archived.sort_by_key(|task| std::cmp::Reverse(task.updated_at));

    Ok(WorkspaceDashboard {
        workspace,
        generated_at: now,
        metrics,
        tasks: summaries,
        attention,
        archived,
    })
}

fn parse_page_cursor(cursor: Option<&str>, label: &str) -> Result<Option<i64>, String> {
    let Some(cursor) = cursor.map(str::trim).filter(|value| !value.is_empty()) else {
        return Ok(None);
    };
    let parsed = cursor
        .parse::<i64>()
        .map_err(|_| format!("invalid {label} cursor"))?;
    if parsed < 0 {
        return Err(format!("invalid {label} cursor"));
    }
    Ok(Some(parsed))
}

fn run_for_activity_event(runs: &[AgentRun], event: &TaskEvent) -> Option<AgentRun> {
    runs.iter()
        .filter(|run| run.branch_id == event.branch_id && run.started_at <= event.created_at)
        .max_by_key(|run| run.started_at)
        .cloned()
        .or_else(|| {
            runs.iter()
                .find(|run| run.branch_id == event.branch_id)
                .cloned()
        })
        .or_else(|| runs.first().cloned())
}

fn activity_presentation(event: &TaskEvent, run: Option<&AgentRun>) -> (String, String) {
    let agent = dashboard_agent_label(run);
    match event.event_type {
        TaskEventType::TaskCreated => ("创建了任务".to_string(), "你".to_string()),
        TaskEventType::StateChanged => ("更新了任务状态".to_string(), agent),
        TaskEventType::RunStarted => ("开始执行".to_string(), agent),
        TaskEventType::RunEnded => ("完成了一次执行".to_string(), agent),
        TaskEventType::UserSteered => ("补充了执行指令".to_string(), "你".to_string()),
        TaskEventType::UserMessageQueued => ("将消息加入队列".to_string(), "你".to_string()),
        TaskEventType::QueueDispatched => ("发送了队列消息".to_string(), "系统".to_string()),
        TaskEventType::RunAborted => ("停止了执行".to_string(), "你".to_string()),
        TaskEventType::SessionBranched => ("创建了会话分支".to_string(), "你".to_string()),
        TaskEventType::SessionCleared => ("清空了会话上下文".to_string(), "你".to_string()),
        TaskEventType::SubagentStarted => ("启动了子代理".to_string(), "子代理".to_string()),
        TaskEventType::SubagentFinished => ("子代理已完成".to_string(), "子代理".to_string()),
        TaskEventType::ToolCall => ("调用了工具".to_string(), agent),
        TaskEventType::ToolResult => ("收到了工具结果".to_string(), agent),
        TaskEventType::PermissionRequested => ("请求了权限".to_string(), agent),
        TaskEventType::PermissionDecided => ("完成了权限裁决".to_string(), "你".to_string()),
        TaskEventType::FileChanged => ("修改了文件".to_string(), agent),
        TaskEventType::VerificationRun => ("运行了验证".to_string(), agent),
        TaskEventType::ChangeRequested => ("请求继续修改".to_string(), "你".to_string()),
        TaskEventType::System => ("更新了系统记录".to_string(), "系统".to_string()),
    }
}

fn build_activity_page(
    state: &CommandState,
    events: Vec<TaskEvent>,
) -> Result<ProjectActivityPage, String> {
    let next_cursor = events.last().map(|event| event.id.to_string());
    let tasks = TaskRepository::new(&state.db);
    let runs = AgentRunRepository::new(&state.db);
    let mut task_cache: HashMap<String, Task> = HashMap::new();
    let mut run_cache: HashMap<String, Vec<AgentRun>> = HashMap::new();
    let mut items = Vec::with_capacity(events.len());

    for event in events {
        let task = if let Some(task) = task_cache.get(&event.task_id) {
            task.clone()
        } else {
            let task = tasks
                .get(&event.task_id)
                .map_err(err_str)?
                .ok_or_else(|| format!("task missing for activity event: {}", event.task_id))?;
            task_cache.insert(event.task_id.clone(), task.clone());
            task
        };
        let task_runs = if let Some(cached) = run_cache.get(&event.task_id) {
            cached.clone()
        } else {
            let records = runs.list_by_task(&event.task_id).map_err(err_str)?;
            run_cache.insert(event.task_id.clone(), records.clone());
            records
        };
        let run = run_for_activity_event(&task_runs, &event);
        let (summary, actor) = activity_presentation(&event, run.as_ref());
        items.push(ProjectActivityItem {
            id: event.id.to_string(),
            at: event.created_at,
            kind: event.event_type,
            summary,
            task_id: task.id.clone(),
            task_title: display_task_title(&task),
            workspace_path: task.workspace_path.clone(),
            run_id: run.as_ref().map(|item| item.id.clone()),
            actor: Some(actor),
            metadata: serde_json::json!({
                "event_id": event.id,
                "branch_id": event.branch_id,
                "task_state": task.state.to_string(),
                "run_id": run.as_ref().map(|item| item.id.clone()),
            }),
        });
    }

    Ok(ProjectActivityPage { items, next_cursor })
}

/// 读取一个项目的真实、可分页活动流。
pub async fn project_activity_list(
    state: &CommandState,
    workspace_path: &str,
    cursor: Option<&str>,
    limit: u32,
) -> Result<ProjectActivityPage, String> {
    let workspace = WorkspaceService::new(&state.db)
        .get(workspace_path)
        .map_err(err_str)?
        .ok_or_else(|| {
            "workspace is not open; choose the folder before viewing its activity".to_string()
        })?;
    let cursor = parse_page_cursor(cursor, "project activity")?;
    let events = TaskEventStore::new(&state.db)
        .list_by_workspace_recent(&workspace.canonical_path, cursor, limit)
        .map_err(err_str)?;
    build_activity_page(state, events)
}

/// 读取跨项目的真实、可分页活动流。
pub async fn activity_list(
    state: &CommandState,
    cursor: Option<&str>,
    limit: u32,
) -> Result<ProjectActivityPage, String> {
    let cursor = parse_page_cursor(cursor, "activity")?;
    let events = TaskEventStore::new(&state.db)
        .list_recent(cursor, limit)
        .map_err(err_str)?;
    build_activity_page(state, events)
}

fn review_notification_source_key(task_id: &str, run: Option<&AgentRun>) -> String {
    crate::native_notification::review_source_key(task_id, run.map(|record| record.id.as_str()))
}

async fn sync_notifications(state: &CommandState, locale: &str) -> Result<(), String> {
    let tasks = TaskRepository::new(&state.db)
        .list(None, None, false)
        .map_err(err_str)?;
    let notifications = NotificationRepository::new(&state.db);
    let runs = AgentRunRepository::new(&state.db);
    let localizer = crate::native_notification::NativeLocalizer::for_locale(locale);

    for task in tasks {
        let task_title = task.title.trim();
        let task_title = if !task_title.is_empty() {
            task_title.to_string()
        } else if !task.goal.trim().is_empty() {
            task.goal.trim().to_string()
        } else {
            localizer.text("notifications.unnamedTask", &[])
        };
        for permission in state.permission_engine.pending_for_task(&task.id).await {
            let body = if permission.input_summary.trim().is_empty() {
                localizer.text(
                    "notifications.native.permissionBody",
                    &[("tool", &permission.tool_name)],
                )
            } else {
                permission.input_summary.clone()
            };
            let notification = Notification::new(
                NotificationKind::PermissionRequested,
                localizer.text(
                    "notifications.native.permissionTitle",
                    &[("task", &task_title)],
                ),
                body,
                Some(task.id.clone()),
                task.workspace_path.clone(),
            );
            notifications
                .upsert(
                    &crate::native_notification::permission_source_key(&permission.id),
                    &notification,
                )
                .map_err(err_str)?;
        }

        let latest_run = runs.get_latest_main_run(&task.id).map_err(err_str)?;
        if task.state == TaskState::ReviewReady {
            let source_key = review_notification_source_key(&task.id, latest_run.as_ref());
            notifications
                .mark_task_source_prefix_read(&task.id, "review:", Some(&source_key))
                .map_err(err_str)?;
            let notification = Notification::new(
                NotificationKind::ReviewReady,
                localizer.text("notifications.native.reviewTitle", &[("task", &task_title)]),
                localizer.text("notifications.native.reviewBody", &[]),
                Some(task.id.clone()),
                task.workspace_path.clone(),
            );
            notifications
                .upsert(&source_key, &notification)
                .map_err(err_str)?;
        } else {
            notifications
                .mark_task_source_prefix_read(&task.id, "review:", None)
                .map_err(err_str)?;
        }

        if let Some(run) = latest_run
            .as_ref()
            .filter(|run| run.ended_at.is_some() && run.review_state == ReviewState::Failed)
        {
            let notification = Notification::new(
                NotificationKind::RunFailed,
                localizer.text(
                    "notifications.native.failureTitle",
                    &[("task", &task_title)],
                ),
                localizer.text("notifications.native.failureBody", &[]),
                Some(task.id.clone()),
                task.workspace_path.clone(),
            );
            notifications
                .upsert(
                    &crate::native_notification::run_failure_source_key(&task.id, &run.id),
                    &notification,
                )
                .map_err(err_str)?;
        }
    }
    Ok(())
}

fn mark_current_review_notification_read(
    state: &CommandState,
    task_id: &str,
) -> Result<(), String> {
    let run = AgentRunRepository::new(&state.db)
        .get_latest_main_run(task_id)
        .map_err(err_str)?;
    NotificationRepository::new(&state.db)
        .mark_source_read(&review_notification_source_key(task_id, run.as_ref()))
        .map_err(err_str)
}

/// 读取通知中心；每次读取会先把当前待授权 / 待审查状态同步成幂等通知。
pub async fn notification_list(
    state: &CommandState,
    cursor: Option<&str>,
    limit: u32,
    unread_only: bool,
) -> Result<NotificationPage, String> {
    notification_list_for_locale(state, cursor, limit, unread_only, "zh-CN").await
}

/// Tauri/WebView entry: synchronize Notification Center copy in the active interface locale.
pub async fn notification_list_for_locale(
    state: &CommandState,
    cursor: Option<&str>,
    limit: u32,
    unread_only: bool,
    locale: &str,
) -> Result<NotificationPage, String> {
    sync_notifications(state, locale).await?;
    let cursor = parse_page_cursor(cursor, "notification")?;
    let notifications = NotificationRepository::new(&state.db);
    let rows = notifications
        .list(cursor, limit, unread_only)
        .map_err(err_str)?;
    let next_cursor = rows.last().map(|(sequence, _)| sequence.to_string());
    let records = rows
        .into_iter()
        .map(|(_, notification)| notification)
        .collect();
    Ok(NotificationPage {
        notifications: records,
        next_cursor,
        unread_count: notifications.unread_count().map_err(err_str)?,
    })
}

/// 标记一条通知已读。不存在的通知返回 false，便于前端处理已被清理的旧链接。
