fn global_workflow_skill_catalog(state: &CommandState) -> WorkflowSkillCatalog {
    WorkflowSkillCatalog::new(state.config_dir.join("workflow-skills"))
}

fn project_workflow_skill_catalog(
    state: &CommandState,
    workspace_path: &str,
) -> Result<WorkflowSkillCatalog, String> {
    let settings = SettingsService::new(state.config_dir.clone());
    Ok(WorkflowSkillCatalog::new_project(
        settings
            .project_knowledge_dir(workspace_path)
            .map_err(err_str)?
            .join("workflow-skills"),
    ))
}

pub fn workflow_skills_list(
    state: &CommandState,
    workspace_path: Option<&str>,
) -> Result<Vec<ScopedWorkflowSkill>, String> {
    let inherited = workspace_path.is_some();
    let mut skills: Vec<_> = global_workflow_skill_catalog(state)
        .list()
        .map_err(err_str)?
        .into_iter()
        .map(|skill| ScopedWorkflowSkill {
            skill,
            scope: WorkflowSkillScope::Global,
            inherited,
        })
        .collect();
    if let Some(workspace_path) = workspace_path {
        skills.extend(
            project_workflow_skill_catalog(state, workspace_path)?
                .list_custom()
                .map_err(err_str)?
                .into_iter()
                .map(|skill| ScopedWorkflowSkill {
                    skill,
                    scope: WorkflowSkillScope::Project,
                    inherited: false,
                }),
        );
    }
    skills.sort_by(|left, right| {
        let scope_rank = |value: WorkflowSkillScope| match value {
            WorkflowSkillScope::Global => 0u8,
            WorkflowSkillScope::Project => 1u8,
        };
        scope_rank(left.scope)
            .cmp(&scope_rank(right.scope))
            .then_with(|| left.skill.name.cmp(&right.skill.name))
    });
    Ok(skills)
}

pub fn workflow_skill_save(
    state: &CommandState,
    workspace_path: Option<&str>,
    scoped: ScopedWorkflowSkillDraft,
) -> Result<ScopedWorkflowSkill, String> {
    let skill = match scoped.scope {
        WorkflowSkillScope::Global => global_workflow_skill_catalog(state)
            .save(scoped.draft)
            .map_err(err_str)?,
        WorkflowSkillScope::Project => {
            let workspace_path =
                workspace_path.ok_or_else(|| "保存项目 Skill 需要项目作用域".to_string())?;
            if scoped.draft.source != WorkflowSkillSource::Custom {
                return Err("项目作用域只能创建自定义 Skill".to_string());
            }
            if global_workflow_skill_catalog(state)
                .list()
                .map_err(err_str)?
                .iter()
                .any(|skill| skill.name == scoped.draft.name)
            {
                return Err(format!(
                    "Skill 调用名 /{} 已被全局 Skill 使用，请换一个名称",
                    scoped.draft.name
                ));
            }
            project_workflow_skill_catalog(state, workspace_path)?
                .save(scoped.draft)
                .map_err(err_str)?
        }
    };
    Ok(ScopedWorkflowSkill {
        skill,
        scope: scoped.scope,
        inherited: false,
    })
}

pub fn workflow_skill_reset(state: &CommandState, id: &str) -> Result<ScopedWorkflowSkill, String> {
    let skill = global_workflow_skill_catalog(state)
        .reset_builtin(id)
        .map_err(err_str)?;
    Ok(ScopedWorkflowSkill {
        skill,
        scope: WorkflowSkillScope::Global,
        inherited: false,
    })
}

pub fn workflow_skill_delete(
    state: &CommandState,
    workspace_path: Option<&str>,
    scope: WorkflowSkillScope,
    id: &str,
) -> Result<(), String> {
    match scope {
        WorkflowSkillScope::Global => global_workflow_skill_catalog(state),
        WorkflowSkillScope::Project => project_workflow_skill_catalog(
            state,
            workspace_path.ok_or_else(|| "删除项目 Skill 需要项目作用域".to_string())?,
        )?,
    }
    .delete_custom(id)
    .map_err(err_str)
}

pub fn workflow_skill_sync_to_global(
    state: &CommandState,
    workspace_path: &str,
    id: &str,
) -> Result<ScopedWorkflowSkill, String> {
    let skill = project_workflow_skill_catalog(state, workspace_path)?
        .promote_custom_to(id, &global_workflow_skill_catalog(state))
        .map_err(err_str)?;
    Ok(ScopedWorkflowSkill {
        skill,
        scope: WorkflowSkillScope::Global,
        inherited: false,
    })
}

pub fn knowledge_prompts_get(
    state: &CommandState,
    workspace_path: Option<&str>,
) -> Result<serde_json::Value, String> {
    let settings = SettingsService::new(state.config_dir.clone());
    let global = settings.load_agent_prompts().map_err(err_str)?;
    let project = workspace_path
        .map(|path| settings.load_project_agent_prompts(path).map_err(err_str))
        .transpose()?;
    let project_configured = workspace_path
        .map(|path| {
            settings
                .project_agent_prompts_path(path)
                .map(|value| value.exists())
        })
        .transpose()
        .map_err(err_str)?
        .unwrap_or(false);
    let effective = settings
        .resolve_agent_prompts(workspace_path)
        .map_err(err_str)?;
    Ok(serde_json::json!({
        "global": global,
        "project": project,
        "project_configured": project_configured,
        "effective": effective,
    }))
}

pub fn knowledge_prompts_save(
    state: &CommandState,
    workspace_path: Option<&str>,
    mode: ProjectPromptMode,
    main_agent: &str,
    subagent: &str,
) -> Result<serde_json::Value, String> {
    let settings = SettingsService::new(state.config_dir.clone());
    if let Some(workspace_path) = workspace_path {
        settings
            .save_project_agent_prompts(
                workspace_path,
                &ProjectAgentPromptPolicy {
                    mode,
                    main_agent: main_agent.to_string(),
                    subagent: subagent.to_string(),
                },
            )
            .map_err(err_str)?;
    } else {
        settings
            .save_agent_prompts(&r_code_agent_worker::AgentPromptPolicy {
                main_agent: main_agent.to_string(),
                subagent: subagent.to_string(),
            })
            .map_err(err_str)?;
    }
    knowledge_prompts_get(state, workspace_path)
}

pub fn knowledge_prompts_reset(
    state: &CommandState,
    workspace_path: Option<&str>,
) -> Result<serde_json::Value, String> {
    let settings = SettingsService::new(state.config_dir.clone());
    if let Some(workspace_path) = workspace_path {
        settings
            .reset_project_agent_prompts(workspace_path)
            .map_err(err_str)?;
    } else {
        settings.reset_agent_prompts().map_err(err_str)?;
    }
    knowledge_prompts_get(state, workspace_path)
}

/// 将审核反馈作为一个新的用户指令发送给任务，并保留明确的审计事件。
///
/// 该动作只允许发生在 `review_ready`：它不会悄悄接受或回滚现有改动，而是启动
/// 下一轮 Agent 运行，让用户的反馈和后续修改都留在同一会话历史中。
pub async fn change_request(
    state: &CommandState,
    task_id: &str,
    message: &str,
) -> Result<(), String> {
    const MAX_REVIEW_FEEDBACK_CHARS: usize = 8_000;
    let feedback = message.trim();
    if feedback.is_empty() {
        return Err("请说明希望修改的内容".to_string());
    }
    if feedback.chars().count() > MAX_REVIEW_FEEDBACK_CHARS {
        return Err(format!(
            "审核反馈不能超过 {MAX_REVIEW_FEEDBACK_CHARS} 个字符"
        ));
    }
    let task = TaskRepository::new(&state.db)
        .get(task_id)
        .map_err(err_str)?
        .ok_or_else(|| format!("task not found: {task_id}"))?;
    if task.state != TaskState::ReviewReady {
        return Err("只有等待审核的任务可以请求修改".to_string());
    }
    let branch = SessionBranchRepository::new(&state.db)
        .ensure_active(task_id)
        .map_err(err_str)?;
    let reviewed_run = AgentRunRepository::new(&state.db)
        .get_latest_main_run(task_id)
        .map_err(err_str)?;
    let reviewed_source = review_notification_source_key(task_id, reviewed_run.as_ref());
    let instruction =
        format!("审核反馈：\n{feedback}\n\n请根据以上反馈继续修改；完成后说明变更内容与验证结果。");

    agent_send_with_mode(state, task_id, &instruction, AgentSendMode::Auto).await?;
    TaskEventStore::new(&state.db)
        .append_for_branch(task_id, &branch.id, TaskEventType::ChangeRequested)
        .map_err(err_str)?;
    NotificationRepository::new(&state.db)
        .mark_source_read(&reviewed_source)
        .map_err(err_str)?;
    Ok(())
}

/// 简易 unified diff：基于 LCS 的行级对比，变化块上下文 ±3 行，省略段用 hunk 行。
/// 任一侧超过 `MAX_DIFF_LINES` 行时降级为全删全增并标记 truncated。
const MAX_DIFF_LINES: usize = 800;
const DIFF_CTX: usize = 3;

fn build_diff_lines(before: &str, after: &str) -> (Vec<ChangeDiffLine>, bool) {
    let old: Vec<&str> = before.lines().collect();
    let new: Vec<&str> = after.lines().collect();

    if old.len() > MAX_DIFF_LINES || new.len() > MAX_DIFF_LINES {
        let mut lines =
            Vec::with_capacity(old.len().min(MAX_DIFF_LINES) + new.len().min(MAX_DIFF_LINES));
        for (i, l) in old.iter().take(MAX_DIFF_LINES).enumerate() {
            lines.push(ChangeDiffLine {
                line_id: None,
                review_state: None,
                kind: ChangeDiffLineKind::Del,
                text: (*l).into(),
                old_no: Some(i + 1),
                new_no: None,
            });
        }
        for (i, l) in new.iter().take(MAX_DIFF_LINES).enumerate() {
            lines.push(ChangeDiffLine {
                line_id: None,
                review_state: None,
                kind: ChangeDiffLineKind::Add,
                text: (*l).into(),
                old_no: None,
                new_no: Some(i + 1),
            });
        }
        return (lines, true);
    }

    // LCS DP
    let (n, m) = (old.len(), new.len());
    let mut dp = vec![vec![0u32; m + 1]; n + 1];
    for i in (0..n).rev() {
        for j in (0..m).rev() {
            dp[i][j] = if old[i] == new[j] {
                dp[i + 1][j + 1] + 1
            } else {
                dp[i + 1][j].max(dp[i][j + 1])
            };
        }
    }

    // 回溯生成操作序列
    enum Op {
        Ctx(usize, usize),
        Del(usize),
        Add(usize),
    }
    let mut ops = Vec::new();
    let (mut i, mut j) = (0, 0);
    while i < n && j < m {
        if old[i] == new[j] {
            ops.push(Op::Ctx(i, j));
            i += 1;
            j += 1;
        } else if dp[i + 1][j] >= dp[i][j + 1] {
            ops.push(Op::Del(i));
            i += 1;
        } else {
            ops.push(Op::Add(j));
            j += 1;
        }
    }
    while i < n {
        ops.push(Op::Del(i));
        i += 1;
    }
    while j < m {
        ops.push(Op::Add(j));
        j += 1;
    }

    // 上下文收敛：保留变化块 ±DIFF_CTX 行，其余用 hunk 行替代
    let keep: Vec<bool> = {
        let mut k = vec![false; ops.len()];
        let changed: Vec<usize> = ops
            .iter()
            .enumerate()
            .filter_map(|(idx, op)| match op {
                Op::Ctx(..) => None,
                _ => Some(idx),
            })
            .collect();
        for &c in &changed {
            let lo = c.saturating_sub(DIFF_CTX);
            let hi = (c + DIFF_CTX + 1).min(ops.len());
            for slot in k.iter_mut().take(hi).skip(lo) {
                *slot = true;
            }
        }
        k
    };

    let mut lines = Vec::new();
    let mut in_gap = false;
    for (idx, op) in ops.iter().enumerate() {
        if !keep[idx] {
            if !in_gap {
                lines.push(ChangeDiffLine {
                    line_id: None,
                    review_state: None,
                    kind: ChangeDiffLineKind::Hunk,
                    text: "···".into(),
                    old_no: None,
                    new_no: None,
                });
                in_gap = true;
            }
            continue;
        }
        in_gap = false;
        match *op {
            Op::Ctx(o, nn) => lines.push(ChangeDiffLine {
                line_id: None,
                review_state: None,
                kind: ChangeDiffLineKind::Ctx,
                text: old[o].into(),
                old_no: Some(o + 1),
                new_no: Some(nn + 1),
            }),
            Op::Del(o) => lines.push(ChangeDiffLine {
                line_id: None,
                review_state: None,
                kind: ChangeDiffLineKind::Del,
                text: old[o].into(),
                old_no: Some(o + 1),
                new_no: None,
            }),
            Op::Add(nn) => lines.push(ChangeDiffLine {
                line_id: None,
                review_state: None,
                kind: ChangeDiffLineKind::Add,
                text: new[nn].into(),
                old_no: None,
                new_no: Some(nn + 1),
            }),
        }
    }
    (lines, false)
}

pub async fn change_diff(
    state: &CommandState,
    task_id: &str,
    path: &str,
) -> Result<ChangeDiff, String> {
    change_diff_scoped(state, task_id, path, None).await
}

/// 单次运行内的文件 diff。与任务级审核不同，这个入口不会读取另一轮的最新 review
/// snapshot，也不会回退到工作区累计 Git 状态。
pub async fn change_diff_for_run(
    state: &CommandState,
    task_id: &str,
    run_id: &str,
    path: &str,
) -> Result<ChangeDiff, String> {
    change_diff_scoped(state, task_id, path, Some(run_id)).await
}

async fn change_diff_scoped(
    state: &CommandState,
    task_id: &str,
    path: &str,
    run_id: Option<&str>,
) -> Result<ChangeDiff, String> {
    let review = ReviewGitService::new(&state.db, state.blobs_dir.clone());
    let snapshot = match run_id {
        Some(_) => None,
        None => review.file_snapshot(task_id, path).map_err(err_str)?,
    };
    let service = ChangeService::new(&state.db, state.blobs_dir.clone());
    let changes = match run_id {
        Some(run_id) => service.list_changes_for_run(task_id, run_id).await,
        None => service.list_changes(task_id).await,
    }
    .map_err(err_str)?;

    // Prefer the current run-scoped review snapshot. The audit table can contain several runs;
    // falling back to its newest matching row keeps live/legacy previews useful without showing
    // an obsolete first edit forever.
    let normalized_path = path.replace('\\', "/");
    let matches_path = |change: &&FileChange| {
        let candidate = change.path.replace('\\', "/");
        if run_id.is_some() {
            candidate == normalized_path
        } else {
            candidate == normalized_path
                || candidate.ends_with(&normalized_path)
                || normalized_path.ends_with(&candidate)
        }
    };
    let change = if run_id.is_some() {
        // Finalized workspace snapshots are the net run result and therefore outrank any
        // intermediate tool audit rows for the same path.
        changes
            .iter()
            .rev()
            .filter(matches_path)
            .find(|change| change.tool_call_id.is_none())
            .or_else(|| changes.iter().rev().find(matches_path))
    } else {
        changes.iter().rev().find(matches_path)
    };
    if snapshot.is_none() && change.is_none() {
        if let Some(run_id) = run_id {
            return Err(format!(
                "no change recorded for run {run_id} and path: {path}"
            ));
        }
        return workspace_git_change_diff(state, task_id, path);
    }
    let display_path = snapshot
        .as_ref()
        .map(|snapshot| snapshot.path.clone())
        .or_else(|| change.map(|change| change.path.clone()))
        .ok_or_else(|| format!("no change recorded for path: {path}"))?;
    let before_hash = snapshot
        .as_ref()
        .map(|snapshot| snapshot.before_hash.clone())
        .unwrap_or_else(|| change.and_then(|change| change.before_hash.clone()));
    let after_hash = snapshot
        .as_ref()
        .map(|snapshot| snapshot.after_hash.clone())
        .unwrap_or_else(|| change.and_then(|change| change.after_hash.clone()));
    let change_type = change.map(|change| change.change_type);

    let blobs = BlobStore::new(&state.db, state.blobs_dir.clone());
    let read_blob = |hash: &Option<String>| -> Result<Option<String>, String> {
        match hash {
            None => Ok(None),
            Some(h) => blobs
                .get(h)
                .map_err(err_str)?
                .map(|b| String::from_utf8_lossy(&b).into_owned())
                .map(Some)
                .map(Ok)
                .unwrap_or(Ok(None)),
        }
    };
    let before = read_blob(&before_hash)?;
    let after = read_blob(&after_hash)?;

    // 两侧内容都拿不到 → 降级为仅元信息
    if before.is_none() && after.is_none() {
        return Ok(ChangeDiff {
            supported: false,
            path: display_path,
            change_type,
            before_hash,
            after_hash,
            lines: None,
            truncated: None,
        });
    }

    let (mut lines, truncated) = build_diff_lines(
        before.as_deref().unwrap_or(""),
        after.as_deref().unwrap_or(""),
    );
    let decisions = if run_id.is_none() {
        Some(
            review
                .line_decisions(task_id, &display_path)
                .map_err(err_str)?,
        )
    } else {
        None
    };
    for line in &mut lines {
        let kind = match line.kind {
            ChangeDiffLineKind::Add => Some(ReviewDiffLineKind::Add),
            ChangeDiffLineKind::Del => Some(ReviewDiffLineKind::Del),
            ChangeDiffLineKind::Ctx | ChangeDiffLineKind::Hunk => None,
        };
        line.line_id = kind
            .map(|kind| r_code_store::review_line_id(kind, line.old_no, line.new_no, &line.text));
        line.review_state = line.line_id.as_ref().and_then(|line_id| {
            decisions
                .as_ref()
                .and_then(|decisions| decisions.get(line_id).copied())
        });
    }
    Ok(ChangeDiff {
        supported: true,
        path: display_path,
        change_type,
        before_hash,
        after_hash,
        lines: Some(lines),
        truncated: if truncated { Some(true) } else { None },
    })
}

fn workspace_git_change_diff(
    state: &CommandState,
    task_id: &str,
    requested_path: &str,
) -> Result<ChangeDiff, String> {
    let workspace_root = attached_task_workspace_root(state, task_id)?;
    let normalized = requested_path.replace('\\', "/");
    let change = workspace_git_changes(&workspace_root)?
        .into_iter()
        .find(|change| change.display_path == normalized)
        .ok_or_else(|| format!("path is not an uncommitted workspace change: {requested_path}"))?;
    let git = GitService::new(workspace_root.clone());
    let before = git
        .head_tree()
        .map_err(err_str)?
        .map(|tree| git.blob_at_tree(&tree, &change.repo_path))
        .transpose()
        .map_err(err_str)?
        .flatten();
    let after = read_workspace_git_blob(&workspace_root, &change.physical_path)?;
    let before_hash = before.as_deref().map(r_code_store::hash_content);
    let after_hash = after.as_deref().map(r_code_store::hash_content);
    let change_type = Some(git_status_change_type(change.status));

    if before.is_none() && after.is_none() {
        return Ok(ChangeDiff {
            supported: false,
            path: change.display_path,
            change_type,
            before_hash,
            after_hash,
            lines: None,
            truncated: None,
        });
    }

    let before_text = before
        .as_deref()
        .map(String::from_utf8_lossy)
        .unwrap_or_default();
    let after_text = after
        .as_deref()
        .map(String::from_utf8_lossy)
        .unwrap_or_default();
    let (lines, truncated) = build_diff_lines(&before_text, &after_text);
    Ok(ChangeDiff {
        supported: true,
        path: change.display_path,
        change_type,
        before_hash,
        after_hash,
        lines: Some(lines),
        truncated: truncated.then_some(true),
    })
}

/// Read the worktree side of a Git change without following a tracked symlink outside the
/// attached workspace. Git stores a symlink's target text as its blob, not the target file's
/// contents, so mirroring that representation is both safer and more accurate.
fn read_workspace_git_blob(
    workspace_root: &Path,
    physical_path: &Path,
) -> Result<Option<Vec<u8>>, String> {
    let metadata = match std::fs::symlink_metadata(physical_path) {
        Ok(metadata) => metadata,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
        Err(error) => return Err(err_str(error)),
    };
    if metadata.file_type().is_symlink() {
        let target = std::fs::read_link(physical_path).map_err(err_str)?;
        return Ok(Some(target.to_string_lossy().into_owned().into_bytes()));
    }
    if !metadata.is_file() {
        return Ok(None);
    }
    let guard = PathGuard::new(workspace_root.to_path_buf()).map_err(err_str)?;
    let mut handle = guard
        .open_file(physical_path, WorkspaceFileAccess::Read)
        .map_err(err_str)?;
    let mut bytes = Vec::new();
    handle.file_mut().read_to_end(&mut bytes).map_err(err_str)?;
    Ok(Some(bytes))
}

// ============================================================================
// 验证命令
// ============================================================================

pub async fn run_verification(
    state: &CommandState,
    task_id: &str,
    command: &str,
) -> Result<VerificationRecord, String> {
    let workspace_root = attached_task_workspace_root(state, task_id)?;
    // 验证只需要一个合法的 agent_runs 外键（verifications.run_id 是
    // NOT NULL REFERENCES agent_runs(id)，且 PRAGMA foreign_keys=ON）。
    //
    // 原实现在没有活跃 run 时插一条 ended_at=NULL 的主 run，而全仓无人给它收尾：
    // 时间线永久多一条转圈的"运行中"、任务被判定为永久 running、崩溃恢复误报、
    // 还会顶替 get_active_run 让 accept 写到错误的记录上。
    //
    // 而"点验证"的典型时机恰恰是 agent 已经跑完（任务处于 review_ready / idle），
    // 此时 get_active_run 必然是 None —— 所以这是必现而非偶发。
    //
    // 改为：活跃 run → 最近一条主 run → 都没有才补一条**已结束**的占位 run。
    let runs = AgentRunRepository::new(&state.db);
    let run_id = match runs.get_active_run(task_id).map_err(err_str)? {
        Some(active) => active.id,
        None => match runs.get_latest_main_run(task_id).map_err(err_str)? {
            Some(latest) => latest.id,
            None => {
                // 任务从未跑过 agent。占位 run 建出来就是终态，不留 ended_at=NULL。
                // 复用已有的占位 run，避免每点一次验证就多一行。
                match runs
                    .get_verification_placeholder_run(task_id)
                    .map_err(err_str)?
                {
                    Some(existing) => existing.id,
                    None => {
                        let mut placeholder =
                            AgentRun::new(task_id, VERIFICATION_PLACEHOLDER_MODEL);
                        placeholder.ended_at = Some(chrono::Utc::now());
                        runs.create(&placeholder).map_err(err_str)?;
                        placeholder.id
                    }
                }
            }
        },
    };

    let config = VerificationConfig {
        command: command.to_string(),
        timeout_secs: 300,
    };

    VerificationService::new(&state.db, state.blobs_dir.clone())
        .run_verification(task_id, &run_id, &config, &workspace_root)
        .await
        .map_err(err_str)
}

pub async fn verification_list(
    state: &CommandState,
    task_id: &str,
) -> Result<Vec<VerificationRecord>, String> {
    VerificationService::new(&state.db, state.blobs_dir.clone())
        .list_for_task(task_id)
        .await
        .map_err(err_str)
}

