/// Codex CLI 的可用性。不要把 PATH 上一个同名文件的存在误认为 CLI 可运行：
/// Windows App 的受保护安装目录、陈旧 shim 和损坏的 npm 安装都会命中这种误判。
#[derive(Debug, Clone)]
struct CodexCliProbe {
    available: bool,
    path: Option<PathBuf>,
    version: Option<String>,
    source: Option<CodexCliSource>,
    error: Option<&'static str>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CodexCliSource {
    Path,
    NpmGlobal,
    MacosDesktopBundle,
}

impl CodexCliSource {
    const fn as_str(self) -> &'static str {
        match self {
            Self::Path => "path",
            Self::NpmGlobal => "npm_global",
            Self::MacosDesktopBundle => "macos_desktop_bundle",
        }
    }

    const fn display_name(self) -> &'static str {
        match self {
            Self::Path => "系统 PATH",
            Self::NpmGlobal => "npm 全局安装",
            Self::MacosDesktopBundle => "Codex 桌面版内置",
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct CodexCliCandidate {
    path: PathBuf,
    source: CodexCliSource,
}

#[derive(Debug, Default)]
struct CodexCliProbeFailures {
    checked: usize,
    permission_denied: bool,
    timed_out: bool,
}

#[derive(Debug, Clone)]
struct CodexAuthPreflightCache {
    checked_at: Instant,
    cli: CodexCliProbe,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CodexAuthState {
    Authenticated,
    NotAuthenticated,
    Unknown,
}

impl CodexAuthState {
    fn as_str(self) -> &'static str {
        match self {
            Self::Authenticated => "authenticated",
            Self::NotAuthenticated => "not_authenticated",
            Self::Unknown => "unknown",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CodexSetupState {
    InstallCli,
    Login,
    Check,
    Configure,
    Ready,
}

impl CodexSetupState {
    fn from_components(
        cli_available: bool,
        auth_state: CodexAuthState,
        skill_status: &str,
        mcp_server_configured: bool,
    ) -> Self {
        if !cli_available {
            Self::InstallCli
        } else if auth_state == CodexAuthState::NotAuthenticated {
            Self::Login
        } else if auth_state == CodexAuthState::Unknown {
            Self::Check
        } else if skill_status != "up_to_date" || !mcp_server_configured {
            Self::Configure
        } else {
            Self::Ready
        }
    }

    fn as_str(self) -> &'static str {
        match self {
            Self::InstallCli => "install_cli",
            Self::Login => "login",
            Self::Check => "check",
            Self::Configure => "configure",
            Self::Ready => "ready",
        }
    }
}

