    /// 回归：**绝不替用户自动切到 Responses**。
    ///
    /// 目录声明 openai 官方走 Responses，但升级前存下的配置里没有 protocol 字段。
    /// 若此时按目录推断，用户会在毫不知情的情况下换一套 API 和计费方式。
    #[test]
    fn legacy_config_is_never_auto_upgraded_to_responses() {
        let openai = provider_preset("openai").unwrap();
        assert_eq!(openai.protocol, ProviderProtocol::OpenAiResponses);

        let built = build_provider_config("openai", &provider_cfg(openai.base_url, openai.model));
        assert!(
            matches!(built, agent_llm::ProviderConfig::OpenAi { .. }),
            "没存过 protocol 的旧配置必须留在 Chat，实际 {built:?}"
        );
    }

    /// 存了什么就走什么——目录只提供推荐值，不覆盖用户的选择。
    #[test]
    fn stored_protocol_wins_over_the_catalog() {
        let openai = provider_preset("openai").unwrap();

        // 手动选了 Responses 才会走 Responses
        let built = build_provider_config(
            "openai",
            &provider_cfg_with(
                openai.base_url,
                openai.model,
                ProviderProtocol::OpenAiResponses,
            ),
        );
        match built {
            agent_llm::ProviderConfig::Responses { reasoning, .. } => {
                // EncryptedReplay 只对目录里标了 reasoning_replay 的服务打开
                assert_eq!(reasoning, agent_llm::ReasoningMode::EncryptedReplay);
            }
            other => panic!("显式选了 Responses 却没走，实际 {other:?}"),
        }

        // 反过来：目录说 Anthropic，用户偏要 Chat，也照办
        let kimi = provider_preset("kimi").unwrap();
        assert_eq!(kimi.protocol, ProviderProtocol::AnthropicMessages);
        let built = build_provider_config(
            "kimi",
            &provider_cfg_with(kimi.base_url, kimi.model, ProviderProtocol::OpenAiChat),
        );
        assert!(
            matches!(built, agent_llm::ProviderConfig::OpenAi { .. }),
            "用户选的 Chat 被目录覆盖了，实际 {built:?}"
        );
    }

    #[test]
    fn deepseek_identity_survives_manual_protocol_switches_and_custom_gateways() {
        let profile_name = "team-reasoning-service";
        let custom_gateway = "https://relay.internal.example/v1";
        let chat = build_provider_config(
            profile_name,
            &provider_cfg_with_identity(
                custom_gateway,
                "deepseek-v4-pro",
                ProviderProtocol::OpenAiChat,
                "deepseek",
            ),
        );
        assert!(matches!(chat, agent_llm::ProviderConfig::DeepSeek { .. }));

        let responses = build_provider_config(
            profile_name,
            &provider_cfg_with_identity(
                custom_gateway,
                "deepseek-v4-flash",
                ProviderProtocol::OpenAiResponses,
                "deepseek",
            ),
        );
        assert!(matches!(
            responses,
            agent_llm::ProviderConfig::DeepSeekResponses { .. }
        ));

        let pro_responses = build_provider_config(
            profile_name,
            &provider_cfg_with_identity(
                custom_gateway,
                "deepseek-v4-pro",
                ProviderProtocol::OpenAiResponses,
                "deepseek",
            ),
        );
        assert!(matches!(
            pro_responses,
            agent_llm::ProviderConfig::DeepSeekResponses { model, .. }
                if model == "deepseek-v4-pro"
        ));

        let anthropic = build_provider_config(
            profile_name,
            &provider_cfg_with_identity(
                custom_gateway,
                "deepseek-v4-pro",
                ProviderProtocol::AnthropicMessages,
                "deepseek",
            ),
        );
        assert!(matches!(
            anthropic,
            agent_llm::ProviderConfig::DeepSeekAnthropic { .. }
        ));

        for (name, base_url, protocol) in [
            (
                "deepseek",
                "https://api.deepseek.com",
                ProviderProtocol::OpenAiChat,
            ),
            (
                "deepseek_team_gateway",
                custom_gateway,
                ProviderProtocol::OpenAiResponses,
            ),
            (
                "custom",
                "https://api.deepseek.com/anthropic",
                ProviderProtocol::AnthropicMessages,
            ),
        ] {
            let ordinary = build_provider_config(
                name,
                &provider_cfg_with_identity(base_url, "deepseek-v4-flash", protocol, "openai"),
            );
            let is_ordinary = matches!(
                (protocol, ordinary),
                (
                    ProviderProtocol::OpenAiChat,
                    agent_llm::ProviderConfig::OpenAi { .. }
                ) | (
                    ProviderProtocol::OpenAiResponses,
                    agent_llm::ProviderConfig::Responses { .. }
                ) | (
                    ProviderProtocol::AnthropicMessages,
                    agent_llm::ProviderConfig::Anthropic { .. }
                )
            );
            assert!(
                is_ordinary,
                "explicit non-DeepSeek kind must win for {name} ({protocol:?})"
            );
        }

        let lookalike = build_provider_config(
            "custom",
            &provider_cfg_with_identity(
                "https://api.deepseek.com.example/v1",
                "deepseek-v4-flash",
                ProviderProtocol::OpenAiResponses,
                "openai",
            ),
        );
        assert!(matches!(
            lookalike,
            agent_llm::ProviderConfig::Responses { .. }
        ));
    }

    /// 回归：保存路径同样不能把旧配置升级到 Responses。
    ///
    /// 运行时那条「推断永不为 Responses」的规则曾被保存路径绕过——`None` 分支直接
    /// 取 `preset.protocol`，而 openai 的预设协议正是 Responses。于是旧版前端（不发
    /// protocol 字段）一次保存就把配置写成 Responses，运行时再照存值执行。
    #[test]
    fn saving_without_protocol_never_writes_responses() {
        // openai 的预设协议是 Responses，正是最容易被静默升级的那条
        let preset = provider_preset("openai").unwrap();
        assert_eq!(preset.protocol, ProviderProtocol::OpenAiResponses);

        let persisted = protocol_to_persist("openai", preset.base_url, None, None).unwrap();
        assert_eq!(
            persisted,
            ProviderProtocol::OpenAiChat,
            "不带 protocol 的保存把配置升级到了 {persisted:?}"
        );
    }

    /// 用户选过之后，后续不带 protocol 的保存必须沿用他的选择，不能被预设改回去。
    #[test]
    fn saving_without_protocol_keeps_the_stored_choice() {
        let preset = provider_preset("openai").unwrap();
        for stored in [
            ProviderProtocol::OpenAiResponses,
            ProviderProtocol::OpenAiChat,
        ] {
            assert_eq!(
                protocol_to_persist("openai", preset.base_url, None, Some(stored)).unwrap(),
                stored,
                "已存的选择被后续保存冲掉了"
            );
        }
    }

    /// 目录不认的协议要被拒绝，避免存下一个必然 400 的组合。
    #[test]
    fn saving_a_protocol_the_preset_does_not_support_is_rejected() {
        let preset = provider_preset("zhipu_coding").unwrap();
        assert!(!preset.native.contains(&ProviderProtocol::OpenAiResponses));

        let error = protocol_to_persist(
            "zhipu_coding",
            preset.base_url,
            Some("openai_responses"),
            None,
        )
        .unwrap_err();
        assert!(
            error.contains("该地址不支持") && error.contains("openai_chat"),
            "实际报错：{error}"
        );

        // 但地址被改写后不设限：自建网关实现了什么我们无从知道
        let rewritten = "https://relay.example.com/v1";
        let allowed =
            protocol_to_persist("zhipu_coding", rewritten, Some("openai_responses"), None).unwrap();
        assert_eq!(allowed, ProviderProtocol::OpenAiResponses);

        // 写错的字面量要报错，而不是静默落到某个默认值
        let typo = protocol_to_persist("openai", preset.base_url, Some("grpc_whatever"), None)
            .unwrap_err();
        assert!(typo.contains("未知的线路协议"), "实际报错：{typo}");
    }

    /// 只改协议、其它字段不动时，runtime 指纹必须变，否则当前进程不会重建 provider。
    #[test]
    fn protocol_participates_in_the_runtime_fingerprint() {
        let preset = provider_preset("openai").unwrap();
        let chat = provider_cfg_with(preset.base_url, preset.model, ProviderProtocol::OpenAiChat);
        let responses = provider_cfg_with(
            preset.base_url,
            preset.model,
            ProviderProtocol::OpenAiResponses,
        );
        assert_ne!(
            resolve_effective_protocol("openai", &chat),
            resolve_effective_protocol("openai", &responses)
        );
        assert_ne!(
            provider_runtime_config_fingerprint("openai", &chat),
            provider_runtime_config_fingerprint("openai", &responses),
        );

        // 旧配置补上一个与推断结果相同的值时，有效协议没变，不该白白重建 runtime
        let legacy = provider_cfg(preset.base_url, preset.model);
        assert_eq!(
            resolve_effective_protocol("openai", &legacy),
            resolve_effective_protocol("openai", &chat)
        );
    }

    #[test]
    fn native_run_audit_uses_the_resolved_model_instead_of_fingerprint_segments() {
        let kimi = provider_cfg_with_identity(
            "https://api.kimi.com/coding/",
            "k3-256k",
            ProviderProtocol::AnthropicMessages,
            "kimi_coding",
        );
        let mut bridge = AgentBridge::new();
        bridge.fingerprint = Some(provider_runtime_config_fingerprint("kimi", &kimi));
        bridge.resolved_model = Some(kimi.model.clone());

        assert_eq!(
            resolved_native_run_model(None, bridge.resolved_model.as_deref()),
            "k3-256k"
        );
        assert_eq!(
            resolved_native_run_model(Some("conversation-model"), bridge.resolved_model.as_deref()),
            "conversation-model",
            "an explicit conversation model must remain the highest priority"
        );
        assert_ne!(
            resolved_native_run_model(None, bridge.resolved_model.as_deref()),
            "https://api.kimi.com/coding/"
        );
    }

    #[test]
    fn stable_provider_kind_controls_kimi_runtime_and_fingerprint() {
        let kimi = provider_cfg_with_identity(
            "https://api.kimi.com/coding/",
            "k3-256k",
            ProviderProtocol::AnthropicMessages,
            "kimi_coding",
        );
        assert!(matches!(
            build_provider_config("renamed-coding-subscription", &kimi),
            agent_llm::ProviderConfig::KimiCodingAnthropic { .. }
        ));

        let mut ordinary = kimi.clone();
        ordinary.provider_kind = Some("openai".into());
        assert!(matches!(
            build_provider_config("renamed-coding-subscription", &ordinary),
            agent_llm::ProviderConfig::Anthropic { .. }
        ));
        assert_ne!(
            provider_runtime_config_fingerprint("renamed-coding-subscription", &kimi),
            provider_runtime_config_fingerprint("renamed-coding-subscription", &ordinary),
            "changing stable provider identity must rebuild the live runtime"
        );
    }

