    #[tokio::test]
    async fn provider_reasoning_visibility_is_independent_and_defaults_on() {
        let (_dir, state) = setup_state();
        let hidden_name = format!("reasoning-hidden-{}", uuid::Uuid::new_v4());
        let default_name = format!("reasoning-default-{}", uuid::Uuid::new_v4());
        let visible_name = format!("reasoning-visible-{}", uuid::Uuid::new_v4());

        for (name, show_reasoning) in [
            (&hidden_name, Some(false)),
            (&default_name, None),
            (&visible_name, Some(true)),
        ] {
            settings_save_provider(
                &state,
                ProviderSettingsInput {
                    name: name.clone(),
                    provider_kind: None,
                    base_url: "https://api.example.com/v1".into(),
                    model: "test-model".into(),
                    api_key: Some(format!("sk-{name}")),
                    max_tokens: Some(2048),
                    temperature: Some(0.2),
                    protocol: Some(ProviderProtocol::OpenAiChat.as_str().into()),
                    show_reasoning,
                    activate: Some(false),
                },
            )
            .await
            .unwrap();
        }

        let service = SettingsService::new(state.config_dir.clone());
        let stored = service.load_global_unvalidated().unwrap();
        assert!(!stored.providers[&hidden_name].show_reasoning);
        assert!(stored.providers[&default_name].show_reasoning);
        assert!(stored.providers[&visible_name].show_reasoning);

        let hidden_task = task_create_with_agent(
            &state,
            None,
            "隐藏思考",
            "验证历史过滤",
            "ask",
            Some(&hidden_name),
            Some("r_code"),
        )
        .await
        .unwrap();
        let default_task = task_create_with_agent(
            &state,
            None,
            "显示思考",
            "验证历史展示",
            "ask",
            Some(&default_name),
            Some("r_code"),
        )
        .await
        .unwrap();
        let visible_task = task_create_with_agent(
            &state,
            None,
            "显示思考",
            "验证显式展示",
            "ask",
            Some(&visible_name),
            Some("r_code"),
        )
        .await
        .unwrap();
        let reasoning_line = serde_json::to_string(&SessionEvent::System {
            event: R_CODE_REASONING_EVENT.into(),
            data: serde_json::json!({ "text": "公开思考" }),
        })
        .unwrap();
        assert!(session_messages_for_task(
            &state,
            &hidden_task.id,
            &reasoning_line,
            "branch-hidden",
            "storage-hidden",
        )
        .await
        .is_empty());
        assert_eq!(
            session_messages_for_task(
                &state,
                &default_task.id,
                &reasoning_line,
                "branch-default",
                "storage-default",
            )
            .await
            .len(),
            1
        );
        assert_eq!(
            session_messages_for_task(
                &state,
                &visible_task.id,
                &reasoning_line,
                "branch-visible",
                "storage-visible",
            )
            .await
            .len(),
            1
        );

        for name in [&hidden_name, &default_name, &visible_name] {
            service.set_provider_secret(name, "").unwrap();
        }
    }

    #[tokio::test]
    async fn settings_save_roundtrips_and_preserves_stable_provider_identity() {
        let (_dir, state) = setup_state();
        let provider_name = format!("renamed-provider-{}", uuid::Uuid::new_v4());

        settings_save_provider(
            &state,
            ProviderSettingsInput {
                name: provider_name.clone(),
                provider_kind: Some("deepseek".into()),
                base_url: "https://relay.internal.example/v1".into(),
                model: "deepseek-v4-flash".into(),
                api_key: Some("sk-provider-kind-test".into()),
                max_tokens: Some(2048),
                temperature: Some(0.2),
                protocol: Some(ProviderProtocol::OpenAiResponses.as_str().into()),
                show_reasoning: Some(false),
                activate: Some(false),
            },
        )
        .await
        .unwrap();

        let service = SettingsService::new(state.config_dir.clone());
        let stored = service.load_global_unvalidated().unwrap();
        assert_eq!(
            stored.providers[&provider_name].provider_kind.as_deref(),
            Some("deepseek")
        );

        settings_save_provider(
            &state,
            ProviderSettingsInput {
                name: provider_name.clone(),
                provider_kind: None,
                base_url: "https://second-relay.internal.example/v1".into(),
                model: "deepseek-v4-flash".into(),
                api_key: None,
                max_tokens: Some(2048),
                temperature: Some(0.2),
                protocol: None,
                show_reasoning: None,
                activate: Some(false),
            },
        )
        .await
        .unwrap();
        let preserved = service.load_global_unvalidated().unwrap();
        assert_eq!(
            preserved.providers[&provider_name].provider_kind.as_deref(),
            Some("deepseek"),
            "legacy callers that omit provider_kind must preserve the stored identity"
        );
        assert!(
            !preserved.providers[&provider_name].show_reasoning,
            "omitting show_reasoning must preserve the provider's disabled preference"
        );

        settings_save_provider(
            &state,
            ProviderSettingsInput {
                name: provider_name.clone(),
                provider_kind: Some("openai".into()),
                base_url: "https://api.deepseek.com".into(),
                model: "deepseek-v4-pro".into(),
                api_key: None,
                max_tokens: Some(2048),
                temperature: Some(0.2),
                protocol: Some(ProviderProtocol::OpenAiChat.as_str().into()),
                show_reasoning: Some(true),
                activate: Some(false),
            },
        )
        .await
        .unwrap();
        let explicit_other = service.load_global_unvalidated().unwrap();
        assert_eq!(
            explicit_other.providers[&provider_name]
                .provider_kind
                .as_deref(),
            Some("openai"),
            "an explicit identity must win even when the model and host look like DeepSeek"
        );
        assert!(explicit_other.providers[&provider_name].show_reasoning);

        service.set_provider_secret(&provider_name, "").unwrap();
    }

