    #[tokio::test]
    async fn settings_set_round_trips_image_understanding_engine() {
        let (_dir, state) = setup_state();
        // 先落一个就绪的 provider，满足 model 引擎的校验链。
        settings_set(
            &state,
            "providers.openai.base_url",
            serde_json::json!("https://api.openai.com/v1"),
        )
        .await
        .unwrap();
        settings_set(
            &state,
            "providers.openai.model",
            serde_json::json!("gpt-5.5"),
        )
        .await
        .unwrap();
        settings_set(
            &state,
            "providers.openai.api_key",
            serde_json::json!("sk-test"),
        )
        .await
        .unwrap();
        settings_set(
            &state,
            "image_understanding.engine",
            serde_json::json!("model"),
        )
        .await
        .unwrap();
        settings_set(
            &state,
            "image_understanding.model_provider",
            serde_json::json!("openai"),
        )
        .await
        .unwrap();
        settings_set(
            &state,
            "image_understanding.model",
            serde_json::json!("gpt-5.5"),
        )
        .await
        .unwrap();

        let payload = settings_get(&state).await.unwrap();
        assert_eq!(payload["config"]["image_understanding"]["engine"], "model");
        assert_eq!(
            payload["config"]["image_understanding"]["model_provider"],
            "openai"
        );
        assert_eq!(payload["config"]["image_understanding"]["model"], "gpt-5.5");
        let raw = std::fs::read_to_string(state.config_dir.join("config.toml")).unwrap();
        assert!(raw.contains("engine = \"model\""));

        // 切回 OCR：清空模型字段，不留悬空引用。
        settings_set(
            &state,
            "image_understanding.engine",
            serde_json::json!("ocr"),
        )
        .await
        .unwrap();
        settings_set(
            &state,
            "image_understanding.model_provider",
            serde_json::Value::Null,
        )
        .await
        .unwrap();
        settings_set(&state, "image_understanding.model", serde_json::Value::Null)
            .await
            .unwrap();
        let payload = settings_get(&state).await.unwrap();
        assert_eq!(payload["config"]["image_understanding"]["engine"], "ocr");
        assert!(payload["config"]["image_understanding"]
            .get("model_provider")
            .is_none());
    }

    #[cfg(any(target_os = "macos", target_os = "windows"))]
    #[test]
    fn native_ocr_budget_rejects_oversized_or_excess_images() {
        fn fixture(name: &str, width: u32, height: u32) -> ValidatedAttachment {
            let mut bytes = vec![0u8; 24];
            bytes[..8].copy_from_slice(b"\x89PNG\r\n\x1a\n");
            bytes[16..20].copy_from_slice(&width.to_be_bytes());
            bytes[20..24].copy_from_slice(&height.to_be_bytes());
            ValidatedAttachment {
                name: name.to_string(),
                media_type: "image/png".to_string(),
                data: BASE64_STANDARD.encode(&bytes),
                bytes,
                text: None,
                kind: ValidatedAttachmentKind::Image,
                native_ocr: true,
                preview: None,
            }
        }

        assert!(validate_native_ocr_budget(&[fixture("screen.png", 2_000, 1_000)]).is_ok());
        assert!(
            validate_native_ocr_budget(&[fixture("huge.png", 20_000, 10_000)])
                .unwrap_err()
                .contains("单边")
        );
        assert!(validate_native_ocr_budget(&[
            fixture("1.png", 100, 100),
            fixture("2.png", 100, 100),
            fixture("3.png", 100, 100),
            fixture("4.png", 100, 100),
            fixture("5.png", 100, 100),
        ])
        .unwrap_err()
        .contains("最多"));
        let converted = native_ocr_attachment_name("screen.png");
        assert_eq!(converted, "screen.png.ocr.txt");
        assert!(converted.chars().count() <= 180);
    }

    #[test]
    fn queued_attachment_payload_round_trips_preview_ref() {
        let bytes = b"\x89PNG\r\n\x1a\n".to_vec();
        let preview = AttachmentPreviewRef {
            preview_id: "00000000-0000-4000-8000-000000000000".to_string(),
            name: "screen.png".to_string(),
            media_type: "image/png".to_string(),
            ocr_name: "screen.png.ocr.txt".to_string(),
        };
        let attachment = ValidatedAttachment {
            name: preview.ocr_name.clone(),
            media_type: "text/plain".to_string(),
            data: BASE64_STANDARD.encode(&bytes),
            bytes,
            text: Some("OCR text".to_string()),
            kind: ValidatedAttachmentKind::Text,
            native_ocr: false,
            preview: Some(preview.clone()),
        };

        let payload = queued_attachments_payload(&[attachment]).expect("payload");
        let restored = restore_queued_attachments(Some(&payload)).expect("restore");
        assert_eq!(restored.len(), 1);
        assert_eq!(restored[0].preview, Some(preview));
        assert_eq!(restored[0].name, "screen.png.ocr.txt");
    }

