    #[test]
    fn codex_exec_json_parser_keeps_safe_progress_without_private_reasoning() {
        assert!(codex_exec_protocol_progress(
            r#"{"type":"item.started","item":{"type":"future_tool"}}"#
        ));
        assert!(!codex_exec_protocol_progress(
            r#"{"type":"diagnostic.noise","message":"still here"}"#
        ));
        assert!(!codex_exec_protocol_progress("not-json"));
        assert_eq!(
            parse_codex_exec_json_line(
                r#"{"type":"thread.started","thread_id":"thread-123","secret":"ignore"}"#
            ),
            Some(CodexExecJsonEvent::ThreadStarted("thread-123".to_string()))
        );
        assert_eq!(
            parse_codex_exec_json_line(
                r#"{"type":"item.completed","item":{"type":"agent_message","text":"调查完成"}}"#
            ),
            Some(CodexExecJsonEvent::AssistantMessage("调查完成".to_string()))
        );
        assert_eq!(
            parse_codex_exec_json_line(
                r#"{"type":"turn.completed","usage":{"input_tokens":12,"output_tokens":5,"ignored":"secret"}}"#
            ),
            Some(CodexExecJsonEvent::Usage(
                r#"{"input_tokens":12,"output_tokens":5}"#.to_string()
            ))
        );
        assert_eq!(
            parse_codex_exec_json_line(
                r#"{"type":"item.completed","item":{"type":"reasoning","text":"private"}}"#
            ),
            Some(CodexExecJsonEvent::Activity {
                phase: AgentActivityPhase::Finalizing,
                detail: "Codex CLI 已完成一轮分析".to_string(),
            })
        );
        let public_summary = parse_codex_exec_json_line(
            r#"{"type":"item.completed","item":{"type":"reasoning","summary":["已定位委派入口"],"content":["private raw reasoning"]}}"#,
        );
        assert!(matches!(
            public_summary,
            Some(CodexExecJsonEvent::Activity {
                phase: AgentActivityPhase::Requesting,
                detail,
            }) if detail == r#"{"kind":"codex_reasoning_summary","text":"已定位委派入口"}"#
                && !detail.contains("private raw reasoning")
        ));
        assert_eq!(
            safe_codex_reasoning_summary(&serde_json::json!({
                "type": "reasoning",
                "summary": [
                    "**Reviewing the checklist**",
                    { "type": "summary_text", "text": "**Reviewing the checklist**" }
                ],
                "content": ["private raw reasoning"]
            })),
            None,
            "duplicated generic status text should not become a reasoning card"
        );
        assert_eq!(
            safe_codex_reasoning_summary(&serde_json::json!({
                "type": "reasoning",
                "summary": [
                    "**Inspecting `commands.rs` delegation registry**",
                    "Inspecting `commands.rs` delegation registry",
                    "Inspecting `commands.rs` delegation registry and `Composer.tsx`"
                ]
            })),
            Some("Inspecting `commands.rs` delegation registry and `Composer.tsx`".to_string()),
            "Markdown-equivalent and cumulative parts should collapse to the useful form"
        );
        let command = parse_codex_exec_json_line(
            r#"{"type":"item.started","item":{"id":"item-7","type":"command_execution","command":"curl -H 'Authorization: Bearer secret-token' https://example.test","status":"in_progress"}}"#,
        );
        assert!(matches!(
            command,
            Some(CodexExecJsonEvent::ToolStarted { call_id, name, summary })
                if call_id == "item-7"
                    && name == "Codex 命令"
                    && summary.contains("Authorization: ***")
                    && !summary.contains("secret-token")
        ));
        let completed = parse_codex_exec_json_line(
            r#"{"type":"item.completed","item":{"id":"item-7","type":"command_execution","command":"cargo test","status":"completed","aggregated_output":"ok\nAuthorization: Bearer secret-token"}}"#,
        );
        assert!(matches!(
            completed,
            Some(CodexExecJsonEvent::ToolCompleted { call_id, is_error: false, output: Some(output) })
                if call_id == "item-7"
                    && output.contains("ok")
                    && output.contains("Authorization: ***")
                    && !output.contains("secret-token")
        ));
        let app_server_command = serde_json::json!({
            "type": "commandExecution",
            "id": "item-app",
            "command": "rg --files",
            "status": "inProgress"
        });
        assert!(matches!(
            codex_item_tool(&app_server_command),
            Some((call_id, name, summary))
                if call_id == "item-app" && name == "Codex 命令" && summary == "rg --files"
        ));
        let dynamic_delegate = serde_json::json!({
            "type": "dynamicToolCall",
            "id": "delegate-call",
            "tool": CODEX_RCODE_DELEGATE_TOOL,
            "arguments": {
                "label": "storage_review",
                "goal": "审查 database/cache/vector/storage 配置边界",
                "access": "read_only"
            },
            "status": "inProgress"
        });
        assert_eq!(
            codex_item_tool(&dynamic_delegate),
            Some((
                "delegate-call".to_string(),
                "delegate_task".to_string(),
                "storage_review · 审查 database/cache/vector/storage 配置边界".to_string(),
            ))
        );
        // M2-01：rcode_delegate 的白名单输入负载由归一化层构建
        // （codex_interaction::rcode_delegate_safe_input）。
        let mut codex_projection = crate::codex_interaction::CodexRunProjection::new(
            crate::codex_interaction::CodexInteractionCapabilities::for_cli_version(Some(
                "0.145.0",
            )),
            0,
            "run_m2",
            "thr_demo",
            "turn_demo",
        );
        let (_, events, _) = codex_projection.feed_frame(&serde_json::json!({
            "method": "item/started",
            "params": { "threadId": "thr_demo", "turnId": "turn_demo", "item": dynamic_delegate }
        }));
        match events.iter().find(|event| {
            matches!(
                event,
                crate::codex_interaction::CodexTimelineEventV1::ToolStarted { .. }
            )
        }) {
            Some(crate::codex_interaction::CodexTimelineEventV1::ToolStarted {
                safe_input,
                ..
            }) => {
                assert_eq!(
                    safe_input.input_json,
                    Some(serde_json::json!({
                        "agent": "r_code",
                        "label": "storage_review",
                        "goal": "审查 database/cache/vector/storage 配置边界",
                        "access": "read_only"
                    }))
                );
            }
            _ => panic!("expected ToolStarted from dynamic delegate item"),
        }
        let completed_delegate = serde_json::json!({
            "type": "dynamicToolCall",
            "id": "delegate-call",
            "tool": CODEX_RCODE_DELEGATE_TOOL,
            "status": "completed",
            "success": true,
            "contentItems": [{
                "type": "inputText",
                "text": "{\"status\":\"completed\",\"summary\":\"storage review done\",\"token\":\"sk-secret-value\"}"
            }]
        });
        let dynamic_output = safe_codex_tool_output(&completed_delegate)
            .expect("dynamic tool text output should be projected");
        assert!(dynamic_output.contains("storage review done"));
        assert!(!dynamic_output.contains("sk-secret-value"));
        assert!(!codex_item_failed(&completed_delegate));
        assert!(codex_item_failed(&serde_json::json!({
            "type": "dynamicToolCall",
            "status": "failed",
            "success": false
        })));
    }

